window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[103]={"id":"103","numero":103,"titre":"Vertiges","objectifs":[{"id":"103-1","rang":"B","rubrique":"Physiopathologie","titre":"Connaître les mécanismes du syndrome vestibulaire aigu","contenu":"<p>L'appareil vestibulaire assure deux fonctions essentielles : <span class=\"kw-def\">le maintien de l'équilibre de l'axe du corps</span> et <span class=\"kw-def\">la stabilité oculaire pendant le mouvement</span>. Il fonctionne en synergie avec le système proprioceptif et le système visuel.</p>\n\n      <h4>1 · Trois acteurs du contrôle postural</h4>\n      <table >\n        <thead>\n          <tr><th>Acteur</th><th>Rôle</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Récepteurs</strong></td><td>Systèmes sensoriels apportant <span class=\"kw-clinique\">les</span> informations sur la position de la tête et du corps : <span class=\"kw-def\">système vestibulaire</span>, <span class=\"kw-def\">système proprioceptif</span>, <span class=\"kw-def\">système visuel</span>.</td></tr>\n          <tr><td><strong>Intégration</strong></td><td>SNC intègre <span class=\"kw-clinique\">les</span> données des trois systèmes sensoriels.</td></tr>\n          <tr><td><strong>Effecteurs</strong></td><td>Système musculaire du cou, du tronc et des membres → régule la posture.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Système vestibulaire périphérique (oreille interne)</h4>\n      <table >\n        <thead>\n          <tr><th>Structure</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Canaux semi-circulaires</strong> (antérieur, postérieur, latéral)</td><td>Récepteurs sensibles aux <span class=\"kw-bio\">accélérations angulaires</span> de la tête, grâce à leurs <span class=\"kw-def\">crêtes ampullaires</span>. Disposés selon <span class=\"kw-clinique\">les</span> trois plans de l'espace.</td></tr>\n          <tr><td><strong>Macules otolithiques</strong> (utricule + saccule)</td><td>Sensibles à la <span class=\"kw-bio\">position de la tête dans l'espace</span> (mouvements linéaires et direction gravitaire). <br><strong>Utricule :</strong> translations horizontales. <br><strong>Saccule :</strong> translations verticales (mémo : <em>S comme Sol → vertical</em>).</td></tr>\n          <tr><td><strong>Trajet de l'information</strong></td><td>Canaux + macules → <span class=\"kw-def\">nerf vestibulaire</span> → chemine dans le <span class=\"kw-def\">conduit auditif interne</span> (avec le nerf cochléaire) → noyaux vestibulaires.</td></tr>\n          <tr><td><strong>Rapports anatomiques</strong></td><td>Structures vestibulaires et cochléaires intriquées dans le labyrinthe et le CAI : <span class=\"kw-clinique\">une atteinte périphérique associe souvent signes vestibulaires + signes cochléaires</span> (surdité, acouphènes).</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Système vestibulaire central (TC + cervelet)</h4>\n      <table >\n        <thead>\n          <tr><th>Voie efférente</th><th>Cible</th><th>Conséquence si atteinte</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Vestibulo-corticale</strong></td><td>Cortex cérébral (orientation spatiale, perception du mouvement)</td><td><span class=\"kw-alerte\">Vertige</span></td></tr>\n          <tr><td><strong>Vestibulo-oculomotrice</strong></td><td>Noyaux oculomoteurs (stabilisation du regard) <br>Stimulation d'un vestibule → mouvement oculaire <strong>du côté opposé</strong> au vestibule stimulé</td><td><span class=\"kw-alerte\">Nystagmus</span> qui bat du côté opposé à la <span class=\"kw-clinique\">lésion</span></td></tr>\n          <tr><td><strong>Vestibulo-spinale</strong></td><td>Motoneurones médullaires (contrôle postural statique et dynamique)</td><td><span class=\"kw-alerte\">Ataxie vestibulaire</span></td></tr>\n        </tbody>\n      </table>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 414\" role=\"img\" aria-label=\"Schéma des mécanismes du syndrome vestibulaire aigu : les récepteurs vestibulaires de l'oreille interne, c'est-à-dire les canaux semi-circulaires et les macules otolithiques, transmettent l'information par le nerf vestibulaire vers les noyaux vestibulaires du tronc cérébral. De ces noyaux partent trois voies efférentes. La voie vestibulo-oculomotrice se projette vers les noyaux oculomoteurs et son atteinte produit un nystagmus. La voie vestibulo-spinale se projette vers les motoneurones médullaires et son atteinte produit une ataxie vestibulaire. La voie vestibulo-corticale se projette vers le cortex et son atteinte produit le vertige. Un fonctionnement asymétrique entre les deux côtés génère la triade vertige, nystagmus et ataxie.\" style=\"height:auto;display:block;border-radius:8px\">\n          <!-- Récepteurs -->\n          <rect class=\"fb-grey\" x=\"110\" y=\"12\" width=\"340\" height=\"50\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"280\" y=\"33\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\">Récepteurs vestibulaires (oreille interne)</text>\n          <text class=\"tx-grey\" x=\"280\" y=\"50\" text-anchor=\"middle\" font-size=\"11\">canaux semi-circulaires + macules otolithiques</text>\n          <line class=\"ln\" x1=\"280\" y1=\"62\" x2=\"280\" y2=\"78\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,84 275,76 285,76\"/>\n          <!-- Nerf vestibulaire -->\n          <rect class=\"fb-teal\" x=\"155\" y=\"86\" width=\"250\" height=\"40\" rx=\"6\"/>\n          <text class=\"tx-teal\" x=\"280\" y=\"105\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Nerf vestibulaire (VIII)</text>\n          <text class=\"tx-teal\" x=\"280\" y=\"120\" text-anchor=\"middle\" font-size=\"10.5\">conduit auditif interne</text>\n          <line class=\"ln\" x1=\"280\" y1=\"126\" x2=\"280\" y2=\"142\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,148 275,140 285,140\"/>\n          <!-- Noyaux -->\n          <rect class=\"fb-teal\" x=\"155\" y=\"150\" width=\"250\" height=\"40\" rx=\"6\"/>\n          <text class=\"tx-teal\" x=\"280\" y=\"169\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"600\">Noyaux vestibulaires</text>\n          <text class=\"tx-teal\" x=\"280\" y=\"184\" text-anchor=\"middle\" font-size=\"10.5\">tronc cérébral + cervelet vestibulaire</text>\n          <!-- Distribution vers 3 voies -->\n          <line class=\"ln\" x1=\"280\" y1=\"190\" x2=\"280\" y2=\"204\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"100\" y1=\"204\" x2=\"460\" y2=\"204\" stroke-width=\"2\"/>\n          <line class=\"ln\" x1=\"100\" y1=\"204\" x2=\"100\" y2=\"220\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"100,226 95,218 105,218\"/>\n          <line class=\"ln\" x1=\"280\" y1=\"204\" x2=\"280\" y2=\"220\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,226 275,218 285,218\"/>\n          <line class=\"ln\" x1=\"460\" y1=\"204\" x2=\"460\" y2=\"220\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"460,226 455,218 465,218\"/>\n          <!-- 3 voies efférentes -->\n          <rect class=\"fb-purple\" x=\"14\" y=\"228\" width=\"172\" height=\"60\" rx=\"6\"/>\n          <text class=\"tx-purple\" x=\"100\" y=\"249\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Voie oculomotrice</text>\n          <text class=\"tx-purple\" x=\"100\" y=\"265\" text-anchor=\"middle\" font-size=\"10\">vestibulo-oculomotrice</text>\n          <text class=\"tx-purple\" x=\"100\" y=\"279\" text-anchor=\"middle\" font-size=\"10\">→ noyaux oculomoteurs</text>\n          <rect class=\"fb-purple\" x=\"194\" y=\"228\" width=\"172\" height=\"60\" rx=\"6\"/>\n          <text class=\"tx-purple\" x=\"280\" y=\"249\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Voie spinale</text>\n          <text class=\"tx-purple\" x=\"280\" y=\"265\" text-anchor=\"middle\" font-size=\"10\">vestibulo-spinale</text>\n          <text class=\"tx-purple\" x=\"280\" y=\"279\" text-anchor=\"middle\" font-size=\"10\">→ motoneurones médullaires</text>\n          <rect class=\"fb-purple\" x=\"374\" y=\"228\" width=\"172\" height=\"60\" rx=\"6\"/>\n          <text class=\"tx-purple\" x=\"460\" y=\"249\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"600\">Voie corticale</text>\n          <text class=\"tx-purple\" x=\"460\" y=\"265\" text-anchor=\"middle\" font-size=\"10\">vestibulo-corticale</text>\n          <text class=\"tx-purple\" x=\"460\" y=\"279\" text-anchor=\"middle\" font-size=\"10\">→ cortex cérébral</text>\n          <line class=\"ln\" x1=\"100\" y1=\"288\" x2=\"100\" y2=\"304\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"100,310 95,302 105,302\"/>\n          <line class=\"ln\" x1=\"280\" y1=\"288\" x2=\"280\" y2=\"304\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"280,310 275,302 285,302\"/>\n          <line class=\"ln\" x1=\"460\" y1=\"288\" x2=\"460\" y2=\"304\" stroke-width=\"2\"/>\n          <polygon class=\"ah\" points=\"460,310 455,302 465,302\"/>\n          <!-- 3 conséquences -->\n          <rect class=\"fb-red\" x=\"14\" y=\"312\" width=\"172\" height=\"44\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"100\" y=\"333\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Nystagmus</text>\n          <text class=\"tx-red\" x=\"100\" y=\"349\" text-anchor=\"middle\" font-size=\"9\">bat du côté opposé à la <span class=\"kw-clinique\">lésion</span></text>\n          <rect class=\"fb-red\" x=\"194\" y=\"312\" width=\"172\" height=\"44\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"280\" y=\"333\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\">Ataxie vestibulaire</text>\n          <text class=\"tx-red\" x=\"280\" y=\"349\" text-anchor=\"middle\" font-size=\"10\">déviation posturale</text>\n          <rect class=\"fb-red\" x=\"374\" y=\"312\" width=\"172\" height=\"44\" rx=\"6\"/>\n          <text class=\"tx-red\" x=\"460\" y=\"333\" text-anchor=\"middle\" font-size=\"12.5\" font-weight=\"700\"><span class=\"kw-clinique\">Vertige</span></text>\n          <text class=\"tx-red\" x=\"460\" y=\"349\" text-anchor=\"middle\" font-size=\"10\">illusion de mouvement</text>\n          <!-- Synthèse triade -->\n          <rect class=\"fb-amber\" x=\"60\" y=\"366\" width=\"440\" height=\"44\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"280\" y=\"384\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"600\"><tspan x=\"280\">Fonctionnement asymétrique aigu →</tspan><tspan x=\"280\" dy=\"14\">triade vert<span class=\"kw-chiffre\">ige</span> + nystagmus + ataxie</tspan></text>\n        </svg>\n        <figcaption>Du capteur au symptôme : une lésion aiguë rompt la symétrie entre <span class=\"kw-clinique\">les</span> deux vestibules. Une atteinte bilatérale ou chronique donne surtout de l'ataxie, sans vertige ni nystagmus.</figcaption>\n      </figure>\n\n      <div class=\"callout callout-info\">\n        <strong>Mécanisme du syndrome vestibulaire aigu.</strong> Un processus lésionnel aigu (vasculaire, <span class=\"kw-etio\">viral</span>, traumatique…) d'une structure vestibulaire entraîne un <span class=\"kw-def\">fonctionnement asymétrique</span> entre <span class=\"kw-clinique\">les</span> deux côtés → apparition de la triade : <span class=\"kw-clinique\">vertige</span> + <span class=\"kw-clinique\">nystagmus</span> + <span class=\"kw-clinique\">ataxie vestibulaire</span>. Une atteinte <span class=\"kw-def\">bilatérale ou chronique</span> donne au contraire surtout de l'ataxie, <strong>sans <span class=\"kw-clinique\">vertige</span> ni nystagmus</strong>.\n      </div>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Cervelet vestibulaire.</strong> Une atteinte isolée du <span class=\"kw-def\">lobe floculo-nodulaire</span> (archéocervelet, partie basse du cervelet) se traduit cliniquement par un syndrome vestibulaire — d'où la nécessité d'évoquer un <span class=\"kw-alerte\">infarctus cérébelleux</span> devant tout grand <span class=\"kw-clinique\">vertige</span> aigu prolongé isolé.\n      </div>","frequence":0},{"id":"103-2","rang":"A","rubrique":"Définition","titre":"Connaître la définition du vertige","contenu":"<p>Le <strong><span class=\"kw-clinique\">vertige</span></strong> est une <span class=\"kw-def\">illusion de mouvement</span>, soit du patient, soit de l'environnement, qui se traduit le plus souvent par une <span class=\"kw-clinique\">impression de rotation</span> ou parfois de <span class=\"kw-clinique\">déplacement linéaire</span>.</p>\n\n      <table >\n        <thead>\n          <tr><th>Notion</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Sensation</strong></td><td>Illusion de mouvement rotatoire ou linéaire (chute, bascule).</td></tr>\n          <tr><td><strong>Cause</strong></td><td>Atteinte du <span class=\"kw-def\">système d'équilibre au sens large</span> (vestibule, nerf vestibulaire, noyaux vestibulaires, cervelet vestibulaire, voies centrales).</td></tr>\n          <tr><td><strong>Maître symptôme du sd vestibulaire</strong></td><td>Sensation erronée de déplacement, accompagnée de signes neurovégétatifs (<span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">pâleur</span>), d'un nystagmus et de déviations posturales.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>À retenir.</strong> Le terme « <span class=\"kw-clinique\">vertige</span> » est fréquemment utilisé à tort par <span class=\"kw-clinique\">les</span> patients pour désigner d'autres sensations (<span class=\"kw-clinique\">malaise</span>, flou visuel, perte d'équilibre…). Le <span class=\"kw-def\">diagnostic positif</span> repose sur la <span class=\"kw-clinique\">caractérisation précise de l'illusion de mouvement</span> à l'interrogatoire (cf <em>obj-2 et obj-3</em>).\n      </div>","frequence":0},{"id":"103-3","rang":"A","rubrique":"Définition","titre":"Connaître les éléments du diagnostic de vertige et reconnaître les diagnostics différentiels","contenu":"<p>Le diagnostic de <span class=\"kw-clinique\">vertige</span> repose sur la mise en évidence d'un <span class=\"kw-def\">syndrome vestibulaire</span> à l'interrogatoire et à l'examen clinique. Tout aussi important : <strong>éliminer <span class=\"kw-clinique\">les</span> diagnostics différentiels</strong>, fréquents et trompeurs.</p>\n\n      <h4>1 · Éléments du syndrome vestibulaire aigu</h4>\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Sensation vertigineuse</strong> (maître symptôme)</td><td>Sensation erronée de déplacement (rotatoire ou non).</td></tr>\n          <tr><td><strong>Signes neurovégétatifs</strong></td><td><span class=\"kw-clinique\">Nausées</span>, <span class=\"kw-clinique\">vomissements</span>, <span class=\"kw-clinique\">pâleur</span>, <span class=\"kw-clinique\">sueurs</span>, <span class=\"kw-clinique\">diarrhées</span>.</td></tr>\n          <tr><td><strong>Nystagmus</strong></td><td>Réponse motrice du réflexe vestibulo-oculaire : déviation lente de l'œil + secousse de rappel rapide (qui définit le sens du nystagmus).</td></tr>\n          <tr><td><strong>Déviations posturales</strong> axiales et segmentaires</td><td>Réponses motrices du réflexe vestibulo-spinal : déviation des bras à la manœuvre des bras tendus, déviation du corps au test de Romberg.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Diagnostics différentiels — ce qui n'est PAS un <span class=\"kw-clinique\">vertige</span></h4>\n      <table >\n        <thead>\n          <tr><th>Symptôme évoqué à tort</th><th>Vraie origine</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Flou visuel, myodésopsies</strong></td><td>Origine ophtalmologique.</td></tr>\n          <tr><td><strong>Lipothymies, malaises vagaux</strong></td><td><span class=\"kw-clinique\">Hypotension</span> orthostatique, vasovagal.</td></tr>\n          <tr><td><strong>Crises d'<span class=\"kw-def\">épilepsie</span></strong></td><td>Origine neurologique — <span class=\"kw-alerte\">la perte de connaissance n'est JAMAIS d'origine vestibulaire</span>.</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Palpitations</span> irrégulières</strong></td><td>Troubles du rythme cardiaque.</td></tr>\n          <tr><td><strong>Agoraphobie, crises de panique</strong></td><td>Manifestations phobiques, manque de confiance en son équilibre.</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Drapeau diagnostique.</strong> Toute <span class=\"kw-alerte\">perte de connaissance associée n'est jamais d'origine vestibulaire</span>. Devant un patient qui dit « avoir un <span class=\"kw-clinique\">vertige</span> » mais qui décrit en réalité un <span class=\"kw-clinique\">malaise</span> lipothymique, une <span class=\"kw-clinique\">lipothymie</span> ou une perte de <span class=\"kw-def\">contact</span>, il faut explorer une cause cardiaque, neurologique ou métabolique — <strong>pas vestibulaire</strong>.\n      </div>","frequence":1},{"id":"103-4","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les éléments de l’interrogatoire d’un patient vertigineux","contenu":"<p>L'interrogatoire est <span class=\"kw-def\">l'étape clé</span> du <span class=\"kw-def\">diagnostic étiologique</span> : la durée du <span class=\"kw-clinique\">vertige</span> et ses circonstances d'apparition sont <span class=\"kw-clinique\">les</span> meilleurs éléments d'orientation.</p>\n\n      <h4>1 · Caractérisation du symptôme</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Précisions à recueillir</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Type de sensation</strong></td><td>Rotation vraie ? Déplacement linéaire ? Sensation de tangage / de chute ? Distinguer de la <span class=\"kw-clinique\">lipothymie</span>, du <span class=\"kw-clinique\">malaise</span>, du flou visuel.</td></tr>\n          <tr><td><strong>Mode d'installation</strong></td><td>Brutal (névrite, <span class=\"kw-def\">AVC</span>) ? Progressif (schwannome) ? Récidivant (Ménière, <span class=\"kw-def\">migraine</span> vestibulaire) ?</td></tr>\n          <tr><td><strong>Durée</strong></td><td>Quelques secondes (VPPB) → quelques minutes-heures (Ménière, <span class=\"kw-def\">migraine</span>) → plusieurs heures-jours (névrite, <span class=\"kw-def\">AVC</span>) → permanent (schwannome).</td></tr>\n          <tr><td><strong>Circonstances déclenchantes</strong></td><td>Mouvement de tête (VPPB) ? Spontané ? Effort à glotte fermée / pression / bruit fort (<span class=\"kw-clinique\">fistule</span> labyrinthique) ?</td></tr>\n          <tr><td><strong>Fréquence et <span class=\"kw-clinique\">évolution</span></strong></td><td>Crise unique, récurrente, permanente. <span class=\"kw-clinique\">Évolution</span> sur jours/semaines.</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Signes associés à rechercher systématiquement</h4>\n      <table >\n        <thead>\n          <tr><th>Sphère</th><th>Signes</th><th>Orientation</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Cochléaire</strong></td><td>Hypoacousie, acouphènes, sensation d'oreille bouchée</td><td>Ménière, schwannome, labyrinthite, <span class=\"kw-clinique\">fistule</span></td></tr>\n          <tr><td><strong>Otologique</strong></td><td>Otorrhée, <span class=\"kw-clinique\">otalgie</span>, ATCD d'otite</td><td>Cholestéatome, labyrinthite otogène</td></tr>\n          <tr><td><strong>Neurologique</strong></td><td><span class=\"kw-clinique\">Céphalées</span>, <span class=\"kw-clinique\">dysarthrie</span>, diplopie, <span class=\"kw-clinique\">déficit moteur</span>, <span class=\"kw-clinique\">paresthésies</span>, troubles visuels</td><td><span class=\"kw-alerte\">AVC vertébrobasilaire</span>, SEP, tumeur fosse postérieure</td></tr>\n          <tr><td><strong>Cervicale</strong></td><td>Cervicalgies, traumatisme cervical, hyperextension prolongée</td><td><span class=\"kw-alerte\">Dissection de l'artère vertébrale</span></td></tr>\n          <tr><td><strong>Migraineuse</strong></td><td>ATCD personnels et familiaux de <span class=\"kw-def\">migraine</span>, photophobie, phonophobie</td><td><span class=\"kw-def\">Migraine</span> vestibulaire</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · <span class=\"kw-def\">Terrain</span> et antécédents</h4>\n      <ul>\n        <li><strong><span class=\"kw-etio\">FRCV</span></strong> (<span class=\"kw-def\">HTA</span>, <span class=\"kw-def\">diabète</span>, <span class=\"kw-etio\">tabac</span>, <span class=\"kw-etio\">dyslipidémie</span>, ATCD vasculaires) → orientation centrale</li>\n        <li><strong>Traumatisme crânien / cervical récent</strong> → fracture du rocher, <span class=\"kw-clinique\">fistule</span>, <span class=\"kw-etio\">dissection</span> vertébrale</li>\n        <li><strong>Barotraumatisme</strong> (plongée, avion) → <span class=\"kw-clinique\">fistule</span> labyrinthique</li>\n        <li><strong>Médicaments ototoxiques</strong> (aminosides) → atteinte cochléovestibulaire</li>\n        <li><strong>Épisode <span class=\"kw-etio\">viral</span> récent</strong> → névrite vestibulaire</li>\n        <li><strong>Âge / sexe</strong> : VPPB chez femme &gt;<span class=\"kw-chiffre\"> 60 ans</span>, <span class=\"kw-def\">migraine</span> vestibulaire chez enfant, SEP chez femme jeune</li>\n      </ul>\n\n      <div class=\"callout callout-info\">\n        <strong>Aphorisme clinique.</strong> « La distinction périphérique <span class=\"kw-bio\">vs</span> central est souvent difficile à l'examen — le <span class=\"kw-def\">meilleur élément d'orientation étiologique reste la durée du vertige et ses circonstances d'apparition</span>. »\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 89 — Altération fonction auditive · 100 — <span class=\"kw-clinique\">Céphalée</span> · 340 — <span class=\"kw-def\">AVC</span></em></p>","frequence":0},{"id":"103-5","rang":"A","rubrique":"Diagnostic positif","titre":"Devant un vertige, savoir diagnostiquer un syndrome vestibulaire","contenu":"<p>Le diagnostic d'un syndrome vestibulaire repose sur la <span class=\"kw-def\">tétrade clinique</span> : <span class=\"kw-clinique\">vertige</span> + signes neurovégétatifs + nystagmus + ataxie vestibulaire. Le bilan se déroule en <strong>3 étapes</strong>, suivies de la <strong>topographie</strong> périphérique <span class=\"kw-bio\">vs</span> centrale.</p>\n\n      <h4>1 · Démarche en 3 étapes</h4>\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Objectif</th><th>Outils</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>1ère étape</strong></td><td>Reconnaître le sd vestibulaire</td><td><span class=\"kw-clinique\">Vertige</span> + signes végétatifs + nystagmus + ataxie posturale (Romberg, manœuvre des index) + ataxie cinétique (marche, Fukuda)</td></tr>\n          <tr><td><strong>2nde étape</strong></td><td>Diagnostic topographique (périph <span class=\"kw-bio\">vs</span> central)</td><td><span class=\"kw-def\">Test HINTS</span> : <strong>H</strong>ead <strong>I</strong>mpulse Test (Halmagyi) + <strong>N</strong>ystagmus + <strong>T</strong>est of the <strong>S</strong>kew. <br>Recherche nystagmus : <span class=\"kw-def\">vidéonystagmoscopie</span> (idéalement), lunettes de Frenzel à défaut</td></tr>\n          <tr><td><strong>3ème étape</strong></td><td>Examen complémentaire général</td><td>Otoscopie, examen ORL complet, examen neurologique</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Examen de l'ataxie vestibulaire</h4>\n      <table >\n        <thead>\n          <tr><th>Test</th><th>Modalité</th><th>Résultat pathologique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Romberg vestibulaire</strong></td><td>Debout, pieds joints, occlusion des yeux</td><td>Inclinaison latérale lente de l'axe du corps <strong>après quelques secondes d'occlusion</strong>, <span class=\"kw-clinique\">toujours du même côté</span></td></tr>\n          <tr><td><strong>Manœuvre des index</strong></td><td>Assis, bras tendus, index pointés, yeux fermés</td><td>Déviation horizontale &gt; 30°, <span class=\"kw-clinique\">du même côté</span> que le Romberg</td></tr>\n          <tr><td><strong>Marche aveugle</strong></td><td>3 pas avant, 3 pas arrière, yeux fermés</td><td><span class=\"kw-clinique\">Marche en étoile</span> (non spécifique : peut être proprio ou orthopédique)</td></tr>\n          <tr><td><strong>Manœuvre de Fukuda</strong></td><td>50 pas sur place, genou à 45°, bras tendus, yeux ouverts puis fermés</td><td>Déviation latéralisée / rotation &gt; 60° ou chute</td></tr>\n          <tr><td><strong>Marche normale / funambule</strong></td><td>Inspection</td><td>Marche ébrieuse avec pulsions latérales / embardées</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Signe négatif important.</strong> Dans l'ataxie vestibulaire, <span class=\"kw-clinique\">pas d'élargissement du polygone de sustentation</span> (contrairement à l'ataxie cérébelleuse).\n      </div>\n\n      <h4>3 · Topographie : périphérique <span class=\"kw-bio\">vs</span> central</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Syndrome vestibulaire <span style=\"color: var(--spe-pneumo);\">périphérique</span></th><th>Syndrome vestibulaire <span style=\"color: var(--danger);\">central</span></th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Atteinte</strong></td><td>Nerf vestibulaire, labyrinthe postérieur</td><td>Noyaux vestibulaires, lobe floculonodulaire du cervelet</td></tr>\n          <tr><td><strong>Signes associés</strong></td><td><span class=\"kw-clinique\">Signes cochléaires souvent présents</span> : acouphènes, hypoacousie (surdité de perception)</td><td><span class=\"kw-alerte\">Signes neurologiques souvent associés</span> (localisateurs d'une atteinte du tronc cérébral). <span class=\"kw-clinique\">Pas de signes cochléaires</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vertige</span></strong></td><td>Rotatoire <span class=\"kw-clinique\">intense</span>, cloue le malade au lit</td><td>Modéré ou absent (sauf grands <span class=\"kw-clinique\">vertiges</span> centraux)</td></tr>\n          <tr><td><strong>Signes végétatifs</strong></td><td>Intenses, <strong>en lien</strong> avec l'intensité du <span class=\"kw-clinique\">vertige</span></td><td>Intensité <strong>non corrélée</strong> au <span class=\"kw-clinique\">vertige</span> (ex. <span class=\"kw-clinique\">vertige</span> léger + <span class=\"kw-clinique\">vomissements</span> = central)</td></tr>\n          <tr><td><strong>Nystagmus</strong></td><td><span class=\"kw-bio\">Horizonto-rotatoire</span> spontané, <strong>inhibé par la fixation</strong>, unidirectionnel</td><td><span class=\"kw-bio\">Multidirectionnel ou pur</span> (vertical / rotatoire), <strong>non inhibé par la fixation</strong>, change de sens selon la position du regard</td></tr>\n          <tr><td><strong>Ataxie</strong></td><td>Déviation posturale axiale <strong>franche</strong> (index, marche en étoile, Romberg labyrinthique)</td><td>Trouble de l'équilibre au 1er plan (sensation de bateau qui tangue)</td></tr>\n          <tr><td><strong>Head Impulse Test (HIT)</strong></td><td>Saccade de refixation du côté de la déviation posturale</td><td><strong>Normal</strong> (regard reste fixé sur la cible) → paradoxalement rassurant... mais évocateur de central !</td></tr>\n          <tr><td><strong>Complet ?</strong></td><td>Complet (tous <span class=\"kw-clinique\">les</span> symptômes présents)</td><td><span class=\"kw-clinique\">Incomplet</span> (symptômes pas tous présents)</td></tr>\n          <tr><td><strong>Harmonieux ?</strong></td><td><span class=\"kw-bio\">Harmonieux</span> : tous <span class=\"kw-clinique\">les</span> mouvements dans la même direction (côté <span class=\"kw-clinique\">lésion</span> si déficitaire / côté sain si irritatif comme Ménière)</td><td><span class=\"kw-alerte\">Dysharmonieux</span> : mouvements dans des directions différentes</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Test HINTS — le combo bedside pour dépister l'<span class=\"kw-def\">AVC</span></h4>\n      <table >\n        <thead>\n          <tr><th>Composante</th><th>Réalisation</th><th>Interprétation</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>H — Head Impulse Test</strong> (Halmagyi)</td><td>Patient fixe le nez de l'examinateur, impulsions brèves rapides de la tête (G/D) → évalue le réflexe vestibulo-oculaire horizontal</td><td>✅ <strong>Normal</strong> : regard reste fixé → <span class=\"kw-alerte\">central</span> ⚠️ <br>❌ <strong>Saccade de refixation</strong> → <span class=\"kw-bio\">périphérique</span> (déficit vestibulaire)</td></tr>\n          <tr><td><strong>N — Nystagmus</strong></td><td>Observation spontanée et dans le regard latéral</td><td><strong>Périphérique :</strong> horizonto-rotatoire, unidirectionnel, inhibé par fixation. <br><strong>Central :</strong> vertical pur, multidirectionnel, gaze nystagmus, non inhibé voire majoré à la fixation</td></tr>\n          <tr><td><strong>T — Test of the Skew</strong></td><td>Cover-test alterné : cacher / découvrir chaque œil successivement</td><td>✅ <strong>Saccade verticale de correction</strong> de l'œil découvert = désalignement vertical = <span class=\"kw-alerte\">central</span> (souvent <span class=\"kw-alerte\">sd de Wallenberg</span>)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ HINTS « central » = 2 ou <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> an</span>omalies parmi :</strong> Head Impulse normal + nystagmus atypique + skew deviation. Cette combinaison est <span class=\"kw-alerte\">plus sensible que l'IRM cérébrale aux premières heures</span> d'un <span class=\"kw-def\">AVC</span> vertébrobasilaire — examen <strong>indispensable</strong> au lit du patient.\n      </div>\n\n      <h4>5 · Exemple : syndrome vestibulaire harmonieux périphérique <strong>droit</strong></h4>\n      <table >\n        <thead>\n          <tr><th>Élément</th><th>Caractéristique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Nystagmus</strong></td><td>Horizonto-rotatoire battant à <strong>gauche</strong> (phase rapide controlatérale à la <span class=\"kw-clinique\">lésion</span> = définit le sens, phase lente vers la lésion = vers la droite)</td></tr>\n          <tr><td><strong>Ataxie</strong></td><td>Latéralisée à <strong>droite</strong> (déviation vers la <span class=\"kw-clinique\">lésion</span>)</td></tr>\n          <tr><td><strong>HIT</strong></td><td>Déficit du réflexe vestibulo-oculaire à <strong>droite</strong></td></tr>\n          <tr><td><strong>Signes végétatifs</strong></td><td>Intenses</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td>Compensation centrale en quelques jours → diminution progressive</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 89 — Altération fonction auditive · 340 — <span class=\"kw-def\">AVC</span> · 101 — <span class=\"kw-clinique\">Paralysie faciale</span></em></p>","frequence":4},{"id":"103-6","rang":"A","rubrique":"Diagnostic positif","titre":"Savoir reconnaître un vertige positionnel paroxystique bénin (VPPB)","contenu":"<p>Le <strong>VPPB</strong> représente <span class=\"kw-bio\">1/3 des consultations pour vertiges</span> et la <span class=\"kw-clinique\">cause la plus fréquente de vertige chez l'adulte</span>. Il survient volontiers chez la femme de &gt;<span class=\"kw-chiffre\"> 60 ans</span> (1ère cause chez le sujet âgé). Sa reconnaissance est <strong>uniquement clinique</strong> (interrogatoire + manœuvre de Dix-Hallpike), sans aucun examen complémentaire si typique.</p>\n\n      <h4>1 · <span class=\"kw-def\">Physiopathologie</span></h4>\n      <ol>\n        <li>Détachement de <span class=\"kw-def\">particules otholitiques</span> provenant de la <span class=\"kw-clinique\">macule</span> utriculaire</li>\n        <li>Dépôt des particules dans le <span class=\"kw-def\">canal semi-circulaire postérieur</span> (sur la crête ampullaire ou dans l'ampoule) — forme la plus fréquente</li>\n        <li>Toute stimulation du canal postérieur → déflexion massive de la crête ampullaire (<span class=\"kw-clinique\">masse</span> exercée par <span class=\"kw-clinique\">les</span> dépôts) → interprétée par le cerveau comme une rotation massive de la tête → <span class=\"kw-clinique\">vertige</span> bref intense</li>\n      </ol>\n\n      <h4>2 · Causes</h4>\n      <ul>\n        <li>Suites immédiates d'un <span class=\"kw-clinique\">traumatisme crânien</span></li>\n        <li>À distance d'une <span class=\"kw-clinique\">névrite vestibulaire</span></li>\n        <li><span class=\"kw-clinique\">Idiopathique</span> le plus souvent (aucune cause retrouvée)</li>\n      </ul>\n\n      <h4>3 · Tableau clinique typique</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Caractéristique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Durée du <span class=\"kw-clinique\">vertige</span></strong></td><td><span class=\"kw-bio\">&lt; 30 secondes</span> (bref +++)</td></tr>\n          <tr><td><strong>Direction</strong></td><td>Rotatoire ou linéaire (sensation de chute dans un trou)</td></tr>\n          <tr><td><strong>Intensité</strong></td><td>Souvent <span class=\"kw-clinique\">intense</span></td></tr>\n          <tr><td><strong>Signes associés</strong></td><td><span class=\"kw-clinique\">Nausées</span> possibles</td></tr>\n          <tr><td><strong>FR déclenchants</strong></td><td><strong>Exclusivement positionnel et reproductible</strong> : <span class=\"kw-clinique\">se retourner dans son lit</span>, <span class=\"kw-clinique\">se lever</span>, <span class=\"kw-clinique\">se coucher</span>, <span class=\"kw-clinique\">regarder en l'air</span></td></tr>\n          <tr><td><strong>Entre <span class=\"kw-clinique\">les</span> crises</strong></td><td>Patients <span class=\"kw-bio\">asymptomatiques</span> entre <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vertiges</span></td></tr>\n          <tr><td><strong>Signes négatifs</strong> ❌</td><td>Pas de syndrome vestibulaire entre <span class=\"kw-clinique\">les</span> crises, pas de signe neurologique, pas de nystagmus spontané, pas de signe cochléaire</td></tr>\n          <tr><td><strong>Durée d'<span class=\"kw-clinique\">évolution</span></strong></td><td>Crise récurrente pendant <span class=\"kw-chiffre\">3 semaines</span> à<span class=\"kw-chiffre\"> 1 mois</span></td></tr>\n          <tr><td><strong>Sujet âgé</strong></td><td>Interrogatoire souvent trompeur — rechercher VPPB devant tout <span class=\"kw-clinique\">trouble de l'équilibre</span> ou <span class=\"kw-clinique\">chute</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Confirmation diagnostique — manœuvre de Dix-Hallpike</h4>\n      <p>Manœuvre <span class=\"kw-def\">diagnostique</span> qui recherche un VPPB par atteinte des canaux semi-circulaires postérieurs droit ou gauche (forme la plus fréquente).</p>\n\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Geste</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>1</td><td>Patient assis sur la table d'examen</td></tr>\n          <tr><td>2</td><td>Tête tournée à <strong>45°</strong> du côté testé</td></tr>\n          <tr><td>3</td><td>Basculer rapidement en <strong>décubitus latéral</strong> avec tête en extension (nez et regard au plafond)</td></tr>\n          <tr><td>4</td><td>Observer pendant 30-60 s (nystagmus + <span class=\"kw-clinique\">vertige</span> reproduit ?)</td></tr>\n          <tr><td>5</td><td>Remise en position assise (observer le nystagmus inversé)</td></tr>\n          <tr><td>6</td><td>Refaire la manœuvre du côté opposé</td></tr>\n        </tbody>\n      </table>\n\n      <h4>5 · Caractéristiques du nystagmus du VPPB</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Caractéristique du VPPB typique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Latence</strong></td><td><span class=\"kw-bio\">5-15 secondes</span> après la manœuvre</td></tr>\n          <tr><td><strong>Direction</strong></td><td><span class=\"kw-bio\">Vertical supérieur + rotatoire battant vers le sol</span> (géotropique)</td></tr>\n          <tr><td><strong>Intensité</strong></td><td><span class=\"kw-bio\">Crescendo puis decrescendo</span> = paroxystique</td></tr>\n          <tr><td><strong>Symptôme associé</strong></td><td>Accompagné d'un <span class=\"kw-clinique\">violent vertige</span></td></tr>\n          <tr><td><strong>Durée</strong></td><td><span class=\"kw-bio\">≤ 1 minute</span> (voire &lt; 30 secondes selon CEN)</td></tr>\n          <tr><td><strong>Inversion</strong></td><td>S'<strong>inverse</strong> lors de la remise en position assise</td></tr>\n          <tr><td><strong>Décubitus controlatéral</strong></td><td>Ne provoque <strong>ni nystagmus ni <span class=\"kw-clinique\">vertige</span></strong></td></tr>\n          <tr><td><strong>Fat<span class=\"kw-chiffre\">iga</span>bilité</strong></td><td>Diminue à la répétition de la manœuvre</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Atypies → <span class=\"kw-imagerie\">IRM</span> cérébrale.</strong> Devant un <span class=\"kw-clinique\">vertige</span> positionnel : <span class=\"kw-alerte\">signes neurologiques</span>, <span class=\"kw-alerte\">nystagmus atypique</span> (pur vertical, non fat<span class=\"kw-chiffre\">iga</span>ble, sans latence), ou <span class=\"kw-alerte\">résistance aux manœuvres libératoires</span> → faire évoquer une cause centrale (tumeur fosse postérieure, SEP, malformation d'Arnold-Chiari) et indiquer une <span class=\"kw-imagerie\">IRM</span> cérébrale.\n      </div>","frequence":3},{"id":"103-7","rang":"A","rubrique":"Étiologies","titre":"Connaître les arguments en faveur des différentes étiologies de vertige","contenu":"<p>L'orientation étiologique repose sur <strong>3 critères</strong> : <span class=\"kw-def\">la durée du vertige</span>, <span class=\"kw-def\">les circonstances d'apparition</span>, et <span class=\"kw-def\">les signes associés</span> (cochléaires, neurologiques, otologiques).</p>\n\n      <h4>1 · <span class=\"kw-def\">Classification</span> topographique des causes</h4>\n      <table >\n        <thead>\n          <tr><th>Localisation</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Endolabyrinthiques</strong></td><td>Maladie de Ménière · Labyrinthite otogène · Ototoxiques (aminosides) · Traumatisme (fracture du rocher) · <span class=\"kw-clinique\">Vertige</span> positionnel paroxystique bénin (VPPB)</td></tr>\n          <tr><td><strong>Rétrolabyrinthiques</strong></td><td>Tumeur de l'angle ponto-cérébelleux (<span class=\"kw-clinique\">neurinome de l'acoustique = schwannome vestibulaire</span>) · Névrite vestibulaire (<span class=\"kw-etio\">virale</span>, <span class=\"kw-etio\">inflammatoire</span>, vasculaire)</td></tr>\n          <tr><td><strong>Centrales</strong></td><td><span class=\"kw-alerte\">AVC ischémique territoire vertébrobasilaire</span> · Hématome de la fosse postérieure · Tumeur du tronc cérébral · <span class=\"kw-alerte\">Sclérose en plaques</span> · <span class=\"kw-clinique\">Abcès</span> du tronc cérébral (<span class=\"kw-def\">méningite</span> <span class=\"kw-etio\">bactérienne</span> / TB) · Malformations charnière cervico-occipitale · <span class=\"kw-def\">Migraine</span> vestibulaire</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Orientation selon la durée (hors contexte d'<span class=\"kw-alerte\">urgence</span>)</h4>\n      <table >\n        <thead>\n          <tr><th>Durée</th><th>Étiologies à évoquer</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>≤ <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>1</span> min</span>ute</strong></td><td><span class=\"kw-clinique\">VPPB</span> : <span class=\"kw-clinique\">vertiges</span> brefs, répétés, positionnels</td></tr>\n          <tr><td><strong>Minutes — heures</strong></td><td><span class=\"kw-clinique\">Maladie de Ménière</span> (avec signes cochléaires) · <span class=\"kw-clinique\">Migraine vestibulaire</span> (avec <span class=\"kw-clinique\">céphalées</span>)</td></tr>\n          <tr><td><strong>Prolongé (heures-jours)</strong></td><td><span class=\"kw-clinique\">Névrite vestibulaire</span> : <span class=\"kw-clinique\">vertige</span> unique et prolongé · <span class=\"kw-clinique\">Schwannome vestibulaire</span> : <span class=\"kw-clinique\">vertiges</span> récurrents prolongés + surdité + acouphènes unilatéraux</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Orientation selon le contexte de survenue</h4>\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Étiologies</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Cause la + fréquente adulte</strong></td><td>VPPB</td></tr>\n          <tr><td><strong>Cause la + fréquente enfant</strong></td><td><span class=\"kw-clinique\">Migraine vestibulaire</span></td></tr>\n          <tr><td><strong>Positionnel paroxystique</strong></td><td>VPPB (le + fréquent) · Intoxication alcoolique aiguë · Schwannome (si signes otologiques) · <span class=\"kw-clinique\">Fistule</span> péri-lymphatique · Lésions cérébelleuses ou bulbo-pontiques (justifie <span class=\"kw-imagerie\">IRM</span> si signes neuro ou résistance aux manœuvres)</td></tr>\n          <tr><td><strong>Récurrent</strong> (minutes-heures, ± signes oto)</td><td>Schwannome vestibulaire · Maladie de Ménière · <span class=\"kw-def\">Migraine</span> vestibulaire</td></tr>\n          <tr><td><strong>Inaugural persistant &gt;<span class=\"kw-chiffre\"> 12 h</span></strong></td><td>Sd vestibulaire destructif : <span class=\"kw-clinique\">névrite vestibulaire</span> (si isolé) · <span class=\"kw-alerte\">infarctus cérébelleux</span> · <span class=\"kw-alerte\">sd de Wallenberg</span> · SEP · <span class=\"kw-alerte\">dissection vertébrale</span> · labyrinthite infectieuse · thrombose AAI · fracture du rocher · commotion labyrinthique</td></tr>\n          <tr><td><strong>Inaugural transitoire</strong> (minutes-1 h)</td><td>1ère manifestation de <span class=\"kw-clinique\">vertiges</span> récurrents (<span class=\"kw-def\">migraine</span>, Ménière) <strong>OU</strong> <span class=\"kw-alerte\">AIT vertébrobasilaire</span> à évoquer en 1er lieu ⭐</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Pièges diagnostiques principaux urgents</h4>\n      <table >\n        <thead>\n          <tr><th>Tableau</th><th>Diagnostic à évoquer</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Sd vestibulaire aigu</strong></td><td>Doit faire évoquer un <span class=\"kw-alerte\">AVC de la fosse postérieure</span></td></tr>\n          <tr><td><strong>Grand <span class=\"kw-clinique\">vertige</span> inaugural prolongé</strong> (heures) <span class=\"kw-alerte\">isolé</span></td><td>Tout sd vestibulaire <strong>périphérique</strong> aigu isolé ⚠️ sans autre signe → <span class=\"kw-alerte\">IRM en urgence</span> pour rechercher un <span class=\"kw-alerte\">infarctus cérébelleux</span> (atteinte du lobe floculo-nodulaire)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vertige</span> inaugural transitoire</strong></td><td><span class=\"kw-alerte\">AIT</span> à évoquer +++</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vertiges</span> positionnels</strong> atypiques</td><td>Tumeurs de la fosse cérébrale postérieure</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-info\">\n        <strong>Démarche clinique synthétique.</strong>\n        <ul>\n          <li><span class=\"kw-clinique\">Vertige + troubles auditifs</span> → otologique (Ménière, schwannome, <span class=\"kw-clinique\">fistule</span>)</li>\n          <li><span class=\"kw-clinique\">Vertige + céphalées / signes neuro</span> → central (<span class=\"kw-def\">AVC</span>, tumeur)</li>\n          <li><span class=\"kw-clinique\">Vertige + cervicalgies</span> → vasculaire (<span class=\"kw-etio\">dissection</span> vertébrale)</li>\n          <li><span class=\"kw-clinique\">Vertige isolé</span> → périphérique (VPPB si bref / névrite si prolongé)</li>\n        </ul>\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 89 — Altération fonction auditive · 100 — <span class=\"kw-clinique\">Céphalée</span> · 104 — SEP · 340 — <span class=\"kw-def\">AVC</span></em></p>","frequence":0},{"id":"103-8","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de vertige unique prolongé","contenu":"<p>Un <span class=\"kw-clinique\">vertige</span> <span class=\"kw-def\">unique, aigu et durable &gt; 12 h</span> définit un <strong>syndrome vestibulaire destructif</strong>. Deux grands cadres à toujours envisager : <span class=\"kw-bio\">périphérique</span> (névrite vestibulaire — le plus fréquent si isolé) et <span class=\"kw-alerte\">central</span> (<span class=\"kw-clinique\">infarctus</span> cérébelleux, Wallenberg, SEP, <span class=\"kw-etio\">dissection</span> vertébrale).</p>\n\n      <h4>1 · Névrite vestibulaire — cause périphérique la plus fréquente</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Cause</strong></td><td>Processus <span class=\"kw-def\">viral, inflammatoire</span> ou plus rarement vasculaire (équivalent vestibulaire de la surdité brusque ou de la PF à frigore)</td></tr>\n          <tr><td><strong>Prodromes</strong></td><td>Épisode <span class=\"kw-clinique\">viral</span> récent peut précéder</td></tr>\n          <tr><td><strong>Mode d'installation</strong></td><td><span class=\"kw-bio\">Brutal</span></td></tr>\n          <tr><td><strong>Durée</strong></td><td><span class=\"kw-bio\">24-48 h</span> (plusieurs jours selon ORL)</td></tr>\n          <tr><td><strong>Horaire</strong></td><td><span class=\"kw-bio\">Permanent</span></td></tr>\n          <tr><td><strong>FR aggravant</strong></td><td>Accentué par <span class=\"kw-clinique\">les</span> mouvements de la tête</td></tr>\n          <tr><td><strong>Sd vestibulaire</strong></td><td><span class=\"kw-bio\">Harmonieux</span> (purement périphérique)</td></tr>\n          <tr><td><strong>Signes négatifs</strong> ❌</td><td><span class=\"kw-clinique\">Pas de céphalée</span>, <span class=\"kw-clinique\">pas de signe neurologique</span>, <span class=\"kw-clinique\">pas de signe cochléaire</span> (atteinte purement vestibulaire ++)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td>Grand <span class=\"kw-clinique\">vertige</span> initial → instabilité progressive sur semaines/mois → compensation centrale (déficit vestibulaire persiste, révélé dans le <span class=\"kw-clinique\">noir</span> ou aux examens vestibulaires)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · <span class=\"kw-clinique\">Infarctus</span> cérébelleux — principal <span class=\"kw-def\">diagnostic différentiel</span> ⚠️</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Atteinte</strong></td><td>Territoire de l'<span class=\"kw-def\">artère cérébelleuse postéro-inférieure (PICA)</span>, au niveau du cervelet vestibulaire</td></tr>\n          <tr><td><strong>Tableau clinique</strong></td><td>Sd vestibulaire aigu isolé avec <span class=\"kw-clinique\">grand vertige</span> (plusieurs heures), <span class=\"kw-clinique\">nausées</span>, <span class=\"kw-clinique\">vomissements</span>. Sd cérébelleux cinétique homolatéral, <span class=\"kw-clinique\">dysarthrie</span> : peuvent être associés</td></tr>\n          <tr><td><strong><span class=\"kw-alerte\">Drapeaux rouges</span> 🚩</strong></td><td><ul>\n            <li><span class=\"kw-alerte\">FRCV</span></li>\n            <li><span class=\"kw-alerte\">Céphalées, cervicalgies</span> (<span class=\"kw-etio\">dissection</span> vertébrale)</li>\n            <li><span class=\"kw-alerte\">Head Impulse Test normal</span> (paradoxal mais évocateur)</li>\n            <li><span class=\"kw-alerte\">Nystagmus vertical pur</span></li>\n            <li><span class=\"kw-alerte\">Nystagmus changeant de direction</span> selon le regard</li>\n            <li><span class=\"kw-alerte\">Skew deviation verticale / diplopie verticale / strabisme vertical</span></li>\n          </ul></td></tr>\n          <tr><td><strong>CAT</strong></td><td>Mutation en USINV si délais de <span class=\"kw-ttt\">thrombolyse</span>/thrombectomie respectés · <span class=\"kw-clinique\">IRM cérébrale en urgence</span> +++</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Autres causes centrales de <span class=\"kw-clinique\">vertige</span> unique prolongé</h4>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Sd de Wallenberg</strong></td><td>Sd alterne sensitif (hypoesthésie thermo-algique hémiface ipsilat + hémicorps controlat) + <span class=\"kw-clinique\">vertige</span> + sd cérébelleux + paralysie IX/X (atteinte rétro-olivaire bulbaire). Skew deviation fréquente.</td></tr>\n          <tr><td><strong>SEP</strong></td><td>Femme jeune, atteinte <span class=\"kw-clinique\">progressive, fluctuante</span>, autres signes neurologiques fluctuants (NORB, troubles sphinctériens, <span class=\"kw-clinique\">paresthésies</span>, signe de Lhermitte)</td></tr>\n          <tr><td><strong><span class=\"kw-etio\">Dissection</span> de l'artère vertébrale</strong></td><td>Secondaire à un <span class=\"kw-clinique\">traumatisme cervical</span> ou une <span class=\"kw-clinique\">activité prolongée tête en hyperextension</span> (yoga, peinture plafond, manipulation cervicale)</td></tr>\n          <tr><td><strong>Labyrinthite infectieuse</strong></td><td>Complication rare et grave des otites chroniques · signes otologiques associés · <span class=\"kw-imagerie\">TDM</span> des rochers</td></tr>\n          <tr><td><strong>Thrombose de l'artère auditive interne</strong> (rare)</td><td>Déficit <span class=\"kw-alerte\">vestibulo-cochléaire unilatéral profond aigu</span></td></tr>\n          <tr><td><strong>Post-traumatique</strong></td><td>Fracture du rocher translabyrinthique · commotion labyrinthique (risque de sd post-commotionnel)</td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Règle d'or.</strong> Devant tout sd vestibulaire <span class=\"kw-alerte\">aigu isolé prolongé &gt; quelques heures sans aucun autre signe</span>, il est <strong>impératif</strong> de réaliser une <span class=\"kw-alerte\">IRM cérébrale en urgence</span> pour éliminer un <span class=\"kw-alerte\">infarctus cérébelleux</span> (atteinte du lobe floculo-nodulaire) — qui mime parfaitement la névrite vestibulaire.\n      </div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-def\">AVC</span> · 104 — SEP · 100 — <span class=\"kw-clinique\">Céphalée</span></em></p>","frequence":2},{"id":"103-9","rang":"B","rubrique":"Étiologies","titre":"Connaître les principales causes de vertige récurrent prolongé","contenu":"<p>Trois causes principales pour un <span class=\"kw-clinique\">vertige</span> <span class=\"kw-def\">récurrent</span> et de <span class=\"kw-def\">durée prolongée</span> (minutes à heures, voire jours) : la <strong>maladie de Ménière</strong>, la <strong><span class=\"kw-def\">migraine</span> vestibulaire</strong>, et le <strong>schwannome vestibulaire</strong>.</p>\n\n      <h4>1 · Maladie de Ménière</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Physiopath.</strong></td><td>Défaut de résorption de l'endolymphe → <span class=\"kw-def\">hydrops labyrinthique</span> = hyperpression des liquides de l'oreille interne (cause possiblement secondaire : <span class=\"kw-etio\">auto-immune</span>, inflammatoire, traumatique, tumorale…)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>Adulte</td></tr>\n          <tr><td><strong>Durée des crises</strong></td><td><span class=\"kw-bio\">&lt; 24 h</span></td></tr>\n          <tr><td><strong>Fréquence</strong></td><td>Très variable (1/an à plusieurs/semaine)</td></tr>\n          <tr><td><strong>Triade typique</strong></td><td>\n            <ul>\n              <li><strong>Signes cochléaires unilatéraux</strong> du côté atteint (souvent premiers) : <span class=\"kw-clinique\">acouphènes graves</span> + <span class=\"kw-clinique\">hypoacousie fluctuante</span></li>\n              <li><strong>Syndrome vestibulaire périphérique controlatéral</strong> (<span class=\"kw-clinique\">lésion</span> irritative) : <span class=\"kw-clinique\">vertiges rotatoires 15 min à plusieurs heures</span> + <span class=\"kw-clinique\">nausées</span> + <span class=\"kw-clinique\">vomissements</span></li>\n              <li><strong>Sensation d'oreille bouchée</strong> ou de pression dans l'oreille atteinte pendant <span class=\"kw-clinique\">les</span> crises (typique)</li>\n            </ul>\n          </td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td>Instabilité permanente remplace <span class=\"kw-clinique\">les</span> <span class=\"kw-clinique\">vertiges</span> · <span class=\"kw-alerte\">bilatéralisation</span> dans <span class=\"kw-chiffre\">10-15%</span> ⚠️ · <span class=\"kw-alerte\">cophose</span> possible</td></tr>\n          <tr><td><strong>Audiogramme</strong></td><td>Surdité de perception unilatérale endocochléaire prédominant sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">fréquences graves</span> (signe caractéristique car les SP prédominent habituellement sur les aigus), <span class=\"kw-clinique\">fluctuante</span></td></tr>\n          <tr><td><strong>Diagnostic</strong></td><td><span class=\"kw-clinique\">Répétition des crises nécessaire</span> (épisode unique ne suffit pas) · <span class=\"kw-imagerie\">IRM</span> des angles ponto-cérébelleux à demander pour éliminer un schwannome</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · <span class=\"kw-def\">Migraine</span> vestibulaire</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-def\">Terrain</span></strong></td><td>ATCD personnels et familiaux de <span class=\"kw-clinique\">migraine</span> · cause la plus fréquente chez l'enfant</td></tr>\n          <tr><td><strong>Manifestations</strong></td><td><ol>\n            <li>Prodromes possibles à type de <span class=\"kw-clinique\">malaise</span></li>\n            <li>Aura visuelle / sensitive possible</li>\n            <li><span class=\"kw-clinique\">Céphalées migraineuses + vertiges de 5 min à 72 h</span> (<strong><span class=\"kw-clinique\">vertige</span> contemporain de la <span class=\"kw-clinique\">céphalée</span></strong>, ne la précède pas contrairement à une aura)</li>\n            <li><span class=\"kw-clinique\">Nausées</span>, <span class=\"kw-clinique\">vomissements</span>, phonophobie, photophobie</li>\n          </ol></td></tr>\n          <tr><td><strong>PEC</strong></td><td>Même que la <span class=\"kw-def\">migraine</span> (cf item 100) · traitement de fond : flunarizine, cinnarizine</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Schwannome vestibulaire (neurinome de l'acoustique)</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td>Tumeur <span class=\"kw-def\">bénigne</span> des cellules de Schwann du nerf vestibulaire (VIII)</td></tr>\n          <tr><td><strong>Syndrome associé</strong></td><td>Évoquer une <span class=\"kw-clinique\">NF2</span> si schwannomes vestibulaires bilatéraux chez le &lt;<span class=\"kw-chiffre\"> 30 ans</span></td></tr>\n          <tr><td><strong>Présentations</strong></td><td>\n            <ul>\n              <li><strong>Début insidieux :</strong> surdité de perception unilatérale d'<span class=\"kw-clinique\">évolution</span> lentement progressive (découverte fortuite +++)</li>\n              <li><strong>Début brutal :</strong> surdité brusque unilatérale, <span class=\"kw-clinique\">paralysie faciale</span> unilatérale</li>\n              <li><strong>Acouphènes</strong> inconstants, plutôt <span class=\"kw-clinique\">aigus</span> (à l'inverse de Ménière)</li>\n              <li><strong>Syndrome vestibulaire</strong> harmonieux inconstant, discret ou accès récurrents de <span class=\"kw-clinique\">vertiges</span></li>\n            </ul>\n          </td></tr>\n          <tr><td><strong>Dogme</strong></td><td>Toute <span class=\"kw-alerte\">surdité unilatérale progressive de l'adulte</span> de cause non évidente → doit faire évoquer un neurinome de l'acoustique</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Diagnostic différentiel</span></strong></td><td>Principal différentiel de la maladie de Ménière</td></tr>\n          <tr><td><strong>Examen clinique</strong></td><td><span class=\"kw-clinique\">Hypoesthésie cornéenne</span> unilatérale · signes vestibulaires spontanés ou provoqués (Halmagyi, secouage de tête)</td></tr>\n          <tr><td><strong>Examens fonctionnels</strong></td><td>Audiométrie : <span class=\"kw-bio\">surdité de perception avec intelligibilité effondrée</span> (courbe en cloche). PEA : <span class=\"kw-bio\">allongement des latences</span> du côté atteint (atteinte rétrocochléaire). Épreuves caloriques : déficit vestibulaire unilatéral</td></tr>\n          <tr><td><strong>Imagerie</strong></td><td><span class=\"kw-imagerie\">IRM</span> CAI + fosse postérieure avec gadolinium · tumeur de l'angle ponto-cérébelleux, centrée sur le CAI, <span class=\"kw-bio\">fortement réhaussée par le PDC</span></td></tr>\n          <tr><td><strong>PEC</strong></td><td><span class=\"kw-def\">Surveillance</span> · <span class=\"kw-ttt\">radiothérapie</span> stéréotaxique · <span class=\"kw-ttt\">chirurgie</span> (selon âge, taille, évolutivité, localisation, symptômes)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Maladie de Ménière <span class=\"kw-bio\">vs</span> Schwannome — différentiel clé</h4>\n      <table >\n        <thead>\n          <tr><th>Critère</th><th>Maladie de Ménière</th><th>Schwannome du VIII</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Vertiges</span></strong></td><td><span class=\"kw-clinique\">Vertiges</span> rotatoires intenses paroxystiques (<span class=\"kw-chiffre\">15 min</span> à plusieurs heures)</td><td>Soit <span class=\"kw-clinique\">vertiges</span> prolongés / permanents discrets, soit accès récurrents de <span class=\"kw-clinique\">vertiges</span> aigus</td></tr>\n          <tr><td><strong>Acouphènes</strong></td><td>Tonalité <span class=\"kw-bio\">grave</span></td><td>Tonalité <span class=\"kw-bio\">aiguë</span></td></tr>\n          <tr><td><strong>Surdité</strong></td><td>Surdité de perception unilatérale <span class=\"kw-def\">endocochléaire</span> prédominant sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">fréquences graves</span></td><td>Surdité de perception unilatérale <span class=\"kw-def\">rétrocochléaire</span> prédominant sur <span class=\"kw-clinique\">les</span> <span class=\"kw-bio\">fréquences aiguës</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 89 — Altération fonction auditive · 100 — <span class=\"kw-clinique\">Céphalée</span> · 101 — <span class=\"kw-clinique\">Paralysie faciale</span></em></p>","frequence":2},{"id":"103-10","rang":"A","rubrique":"Étiologies","titre":"Connaître les principales causes de vertiges avec atteinte otologique associée","contenu":"<p>L'association <span class=\"kw-def\">vertige + signes otologiques</span> (otorrhée, otorragie, anomalie à l'otoscopie, ATCD d'otite) ou <span class=\"kw-def\">vertige + signes cochléaires</span> (surdité, acouphènes) oriente vers une atteinte de l'oreille moyenne ou interne et impose souvent une <span class=\"kw-imagerie\">TDM</span> du rocher.</p>\n\n      <h4>1 · Cholestéatome</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Mécanisme</strong></td><td>Invasion anormale d'épithélium pavimenteux kératinisé dans l'oreille moyenne, avec <span class=\"kw-clinique\">érosion</span> osseuse progressive</td></tr>\n          <tr><td><strong>Clinique</strong></td><td><span class=\"kw-clinique\">Otorrhée chronique fétide</span> · hypoacousie de transmission · à un <span class=\"kw-def\">stade</span> avancé : <span class=\"kw-clinique\">vertiges</span> (effraction labyrinthique) · <span class=\"kw-clinique\">paralysie faciale</span></td></tr>\n          <tr><td><strong>Imagerie</strong></td><td><span class=\"kw-clinique\">TDM des rochers</span> +++ (<span class=\"kw-clinique\">érosion</span> osseuse, opacité de l'oreille moyenne) · <span class=\"kw-imagerie\">IRM</span> avec <span class=\"kw-imagerie\">diffusion</span> pour distinguer du tissu otitique <span class=\"kw-etio\">inflammatoire</span></td></tr>\n          <tr><td><strong>CAT</strong></td><td><span class=\"kw-alerte\">Chirurgie en urgence</span> si effraction labyrinthique (= labyrinthite otogène imminente)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Labyrinthite otogène</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Cause</strong></td><td>Propagation d'une infection de l'oreille moyenne (OMA ou cholestéatome surinfecté) au labyrinthe par :\n            <ul>\n              <li>Voie préformée : <span class=\"kw-clinique\">fistule</span> de la fenêtre ovale ou ronde</li>\n              <li>Effraction de la capsule osseuse : <span class=\"kw-clinique\">fistule</span> du canal semi-circulaire externe</li>\n            </ul>\n          </td></tr>\n          <tr><td><strong>Manifestations</strong></td><td><span class=\"kw-clinique\">Vertige</span> + nystagmus + acouphènes + <span class=\"kw-clinique\">surdité de perception</span> + <span class=\"kw-clinique\">otorrhée</span></td></tr>\n          <tr><td><strong>Signe de la <span class=\"kw-clinique\">fistule</span></strong></td><td>Hyperpression ou <span class=\"kw-def\">dépression</span> d'<span class=\"kw-def\">air</span> dans le conduit (otoscope pneumatique) → <span class=\"kw-clinique\">déclenche vertige et nystagmus</span></td></tr>\n          <tr><td><strong>Imagerie</strong></td><td><span class=\"kw-imagerie\">TDM</span> rocher = visualise la <span class=\"kw-clinique\">fistule</span></td></tr>\n          <tr><td><strong>CAT</strong></td><td>ATB + <span class=\"kw-ttt\">corticothérapie</span> (peuvent suffir si précoces) · <span class=\"kw-alerte\">chirurgie en urgence si cholestéatome</span></td></tr>\n          <tr><td><strong>Risque</strong></td><td><span class=\"kw-alerte\">Ossification cochléaire secondaire</span> (même avec traitement précoce)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Neurolabyrinthite hématogène ou post-<span class=\"kw-def\">méningite</span></h4>\n      <table >\n        <thead>\n          <tr><th>Cause</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">Virale</span> (hématogène)</strong></td><td>Oreillons (surdité unilatérale), <span class=\"kw-clinique\">zona</span> auriculaire (atteinte du VIII), autres virus neurotropes, <span class=\"kw-clinique\">syphilis</span> (exceptionnelle)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Méningite</span> <span class=\"kw-etio\">bactérienne</span></strong></td><td><span class=\"kw-etio\">Pneumocoque</span> ou <span class=\"kw-ttt\">méningocoque</span> · atteinte <span class=\"kw-alerte\">bilatérale +++</span> · surdité totale irréversible et incurable · <span class=\"kw-alerte\">urgence à l'implant cochléaire bilatéral</span> (risque de fibrose + ossification cochléaire secondaire)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Fracture du rocher</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Manifestations</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Translabyrinthique</strong></td><td>Otorragie + <span class=\"kw-clinique\">vertige</span> + <span class=\"kw-clinique\">surdité de perception</span> + <span class=\"kw-clinique\">paralysie faciale</span> immédiate ± fuite de <span class=\"kw-bio\">LCS</span></td></tr>\n          <tr><td><strong>Extra-labyrinthique</strong></td><td>Otorragie + hémotympan + surdité de transmission + <span class=\"kw-clinique\">paralysie faciale</span> secondaire (<span class=\"kw-clinique\">œdème</span>)</td></tr>\n          <tr><td><strong>Commotion labyrinthique</strong></td><td>Sd post-commotionnel possible (<span class=\"kw-clinique\">vertige</span> + acouphènes prolongés sans fracture)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>5 · <span class=\"kw-clinique\">Fistule</span> labyrinthique (barotraumatique ou post-chirurgicale)</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Causes</strong></td><td><span class=\"kw-alerte\">Rupture</span> de la fenêtre ovale (fracture/luxation du stapes) ou ronde (déchirure de la membrane) par <span class=\"kw-clinique\">barotraumatisme</span> (plongée, avion) ou post-chirurgical</td></tr>\n          <tr><td><strong>Manifestation principale</strong></td><td><span class=\"kw-clinique\">Surdité fluctuante</span> (mixte ou de perception en plateau par hydrops a vacuo)</td></tr>\n          <tr><td><strong>Signes associés</strong></td><td>Acouphènes · troubles équilibre fugaces · <span class=\"kw-clinique\">vertige bref déclenché par :</span>\n            <ul>\n              <li>Forçage (Valsalva, mouchage, effort à glotte fermée)</li>\n              <li>Exposition aux bruits forts (<span class=\"kw-def\">effet Tullio</span>)</li>\n              <li>Pression sur le tragus (<span class=\"kw-def\">signe de la fistule</span>)</li>\n              <li>Tympanométrie</li>\n            </ul>\n          </td></tr>\n          <tr><td><strong>Imagerie</strong></td><td><span class=\"kw-imagerie\">TDM</span> : opacité de la niche fenêtre cochléaire, fracture/luxation platine, pneumolabyrinthe possible</td></tr>\n          <tr><td><strong>PEC</strong></td><td><span class=\"kw-alerte\">Urgence chirurgicale</span> : exploration de l'oreille moyenne, colmatage par graisse/périchondre/aponévrose + colle <span class=\"kw-ttt\">biologique</span></td></tr>\n          <tr><td><strong>Risque</strong></td><td>Perte totale des fonctions auditives et vestibulaires du côté atteint</td></tr>\n        </tbody>\n      </table>\n\n      <h4>6 · Schéma diagnostique selon <span class=\"kw-clinique\">les</span> signes associés</h4>\n      <table >\n        <thead>\n          <tr><th>Tableau</th><th>Orientation</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-clinique\">Vertige</span> + otoscopie anormale</strong></td><td>🔵 Cholestéatome · labyrinthite otogène · fracture du rocher · barotraumatisme</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vertige</span> + signes cochléaires</strong> (surdité, acouphènes)</td><td>🔵 Maladie de Ménière · schwannome vestibulaire · <span class=\"kw-clinique\">fistule</span> périlymphatique</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vertige</span> sans signe associé</strong></td><td>🟡 Probable atteinte vestibulaire périphérique isolée (VPPB si bref, névrite si prolongé)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vertige</span> + <span class=\"kw-clinique\">céphalées</span> / signes neuro</strong></td><td>🔴 <span class=\"kw-alerte\">AVC vertébrobasilaire · tumeur fosse postérieure</span></td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vertige</span> + cervicalgies</strong></td><td>🔴 <span class=\"kw-alerte\">Dissection de l'artère vertébrale</span></td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 89 — Altération fonction auditive · 88 — Dysphonie · 101 — <span class=\"kw-clinique\">Paralysie faciale</span></em></p>","frequence":1},{"id":"103-11","rang":"A","rubrique":"Identifier une urgence","titre":"Savoir évoquer un accident vasculaire ischémique dans le territoire vertébrobasilaire devant un syndrome vestibulaire central","contenu":"<p>Tout syndrome vestibulaire <span class=\"kw-def\">central</span> ou <span class=\"kw-def\">aigu prolongé isolé</span> doit faire évoquer un <span class=\"kw-alerte\">AVC vertébrobasilaire</span> (notamment un <span class=\"kw-alerte\">infarctus cérébelleux</span> dans le territoire de la PICA), qui peut <strong>parfaitement mimer une névrite vestibulaire</strong> à la phase initiale. L'enjeu est de ne pas le manquer car la fenêtre thérapeutique (<span class=\"kw-ttt\">thrombolyse</span>, thrombectomie) est étroite.</p>\n\n      <h4>1 · Quand suspecter un <span class=\"kw-def\">AVC</span> vertébrobasilaire ?</h4>\n      <table >\n        <thead>\n          <tr><th>Contexte</th><th>Argument</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Grand <span class=\"kw-clinique\">vertige</span> aigu prolongé isolé</strong></td><td>Sd vestibulaire périphérique aigu durant plusieurs heures, sans aucun autre signe → <span class=\"kw-alerte\">impose une IRM en urgence</span> (peut être un <span class=\"kw-clinique\">infarctus</span> cérébelleux dont la sémio mime la névrite)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Vertige</span> inaugural transitoire</strong> (&lt;<span class=\"kw-chiffre\"> 1 h</span>)</td><td>À évoquer en 1er lieu = <span class=\"kw-alerte\">AIT</span> du territoire vertébrobasilaire (même si le <span class=\"kw-clinique\">vertige</span> isolé n'est pas un symptôme typique d'<span class=\"kw-def\">AIT</span>)</td></tr>\n          <tr><td><strong>Sd vestibulaire central</strong> à l'examen</td><td>Nystagmus atypique (vertical pur, multidirectionnel, non inhibé par fixation) · HIT normal · skew deviation</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · <span class=\"kw-alerte\">Drapeaux rouges</span> 🚩 (à connaître par cœur)</h4>\n      <table >\n        <thead>\n          <tr><th>Drapeau</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong><span class=\"kw-etio\">FRCV</span></strong></td><td><span class=\"kw-def\">HTA</span>, <span class=\"kw-def\">diabète</span>, <span class=\"kw-etio\">dyslipidémie</span>, <span class=\"kw-etio\">tabac</span>, AC/FA, ATCD vasculaire personnel</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Céphalées</span> / cervicalgies</strong></td><td>Évocateur de <span class=\"kw-alerte\">dissection vertébrale</span> (traumatisme cervical, manipulation, hyperextension)</td></tr>\n          <tr><td><strong>HIT normal</strong> (Head Impulse Test)</td><td>Paradoxalement <span class=\"kw-alerte\">évocateur de central</span> — alors que dans la névrite (périph) il est anormal du côté lésé</td></tr>\n          <tr><td><strong>Nystagmus vertical pur</strong></td><td>Très évocateur de <span class=\"kw-clinique\">lésion</span> <span class=\"kw-alerte\">mésencéphalique</span></td></tr>\n          <tr><td><strong>Nystagmus changeant de direction</strong></td><td>Selon la direction du regard = <span class=\"kw-alerte\">central</span></td></tr>\n          <tr><td><strong>Skew deviation</strong></td><td>Désalignement vertical des yeux au cover-test → <span class=\"kw-alerte\">sd de Wallenberg</span> ou autre atteinte du TC</td></tr>\n          <tr><td><strong>Signes neurologiques associés</strong></td><td><span class=\"kw-clinique\">Dysarthrie</span>, diplopie, troubles de la déglutition, <span class=\"kw-clinique\">déficit moteur</span> ou sensitif, sd cérébelleux, atteinte des paires crâniennes</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Le test HINTS — outil bedside indispensable</h4>\n      <p>2 ou <span class=\"kw-chiffre\"<span class=\"kw-chiffre\">>3</span> an</span>omalies parmi : <strong>H</strong>IT normal + <strong>N</strong>ystagmus atypique + <strong>S</strong>kew deviation = <span class=\"kw-alerte\">HINTS central</span> = <span class=\"kw-def\">AVC</span> très probable.</p>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Sensibilité.</strong> Le test HINTS est <span class=\"kw-alerte\">plus sensible que l'IRM cérébrale</span> aux premières heures d'un <span class=\"kw-def\">AVC</span> vertébrobasilaire. Il est donc indispensable et permet de discriminer périphérique <span class=\"kw-bio\">vs</span> central avant même l'imagerie.\n      </div>\n\n      <h4>4 · Étiologies des <span class=\"kw-def\">AVC</span> vertébrobasilaires avec <span class=\"kw-clinique\">vertige</span></h4>\n      <ul>\n        <li><strong><span class=\"kw-clinique\">Infarctus</span> cérébelleux</strong> (territoire de la <span class=\"kw-def\">PICA</span>) : grand <span class=\"kw-clinique\">vertige</span> + <span class=\"kw-clinique\">nausées</span>/<span class=\"kw-clinique\">vomissements</span> + sd cérébelleux ipsilat ± <span class=\"kw-clinique\">dysarthrie</span></li>\n        <li><strong>Sd de Wallenberg</strong> (<span class=\"kw-clinique\">infarctus</span> rétro-olivaire bulbaire) : <span class=\"kw-clinique\">vertige</span> + sd alterne sensitif (hypoesthésie thermoalgique hémiface ipsilat + hémicorps controlat) + sd cérébelleux + paralysie IX/X (<span class=\"kw-clinique\">dysphagie</span>, dysphonie) ± skew deviation</li>\n        <li><strong><span class=\"kw-etio\">Dissection</span> de l'artère vertébrale</strong> : <span class=\"kw-def\">terrain</span> jeune, traumatisme cervical / hyperextension récente, cervicalgies + <span class=\"kw-clinique\">vertige</span> + signes ischémiques fluctuants</li>\n        <li><strong>Sténose / occlusion du tronc basilaire</strong> : <span class=\"kw-alerte\">pronostic vital engagé</span> (locked-in syndrome possible)</li>\n      </ul>\n\n      <h4>5 · CAT</h4>\n      <table >\n        <thead>\n          <tr><th>Étape</th><th>Action</th></tr>\n        </thead>\n        <tbody>\n          <tr><td>1</td><td><span class=\"kw-alerte\">Admission en USINV en urgence</span></td></tr>\n          <tr><td>2</td><td><span class=\"kw-imagerie\">IRM</span> cérébrale en <span class=\"kw-alerte\">urgence</span> (séquences <span class=\"kw-imagerie\">diffusion</span> + <span class=\"kw-imagerie\">FLAIR</span> + TOF + ARM TSAO)</td></tr>\n          <tr><td>3</td><td>Évaluation pour <span class=\"kw-alerte\">thrombolyse</span> (&lt; 4h30) ou <span class=\"kw-alerte\">thrombectomie</span> (&lt;<span class=\"kw-chiffre\"> 6 h</span>, voire plus si mismatch favorable)</td></tr>\n          <tr><td>4</td><td>Bilan étiologique (<span class=\"kw-bio\">ECG</span>, <span class=\"kw-imagerie\">ETT</span>, <span class=\"kw-imagerie\">doppler</span> TSAO, biologie standard)</td></tr>\n          <tr><td>5</td><td><span class=\"kw-def\">Prévention secondaire</span> (<span class=\"kw-ttt\">antiagrégant</span>, <span class=\"kw-ttt\">anticoagulation</span> si <span class=\"kw-etio\">dissection</span> / cardio-<span class=\"kw-etio\">embolique</span>, contrôle <span class=\"kw-etio\">FRCV</span>)</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-def\">AVC</span> · 100 — <span class=\"kw-clinique\">Céphalée</span></em></p>","frequence":3},{"id":"103-12","rang":"B","rubrique":"Examens complémentaires","titre":"Indication des examens d’imagerie devant un vertige","contenu":"<p>Devant un <span class=\"kw-clinique\">vertige</span>, l'imagerie n'est <strong>jamais systématique</strong> : elle est <span class=\"kw-def\">indiquée selon le contexte clinique</span>. Deux modalités principales : <span class=\"kw-def\">IRM cérébrale injectée</span> (recherche cause centrale ou rétrocochléaire) et <span class=\"kw-def\">TDM des rochers</span> (signes otologiques).</p>\n\n      <h4>1 · <span class=\"kw-imagerie\">IRM</span> cérébrale injectée — indications</h4>\n      <p><span class=\"kw-imagerie\">IRM</span> cérébrale avec gadolinium, étude de la fosse postérieure et des TSAO. Indications :</p>\n      <ul>\n        <li><span class=\"kw-clinique\">Syndrome vestibulaire aigu <strong>dysharmonieux</strong></span></li>\n        <li><span class=\"kw-clinique\">Test HINTS évocateur d'une atteinte centrale</span></li>\n        <li><span class=\"kw-clinique\">Signes neurologiques associés</span> au syndrome vestibulaire aigu</li>\n        <li><span class=\"kw-clinique\">VPPB avec atypies</span> ou <strong>persistant malgré plusieurs manœuvres thérapeutiques</strong></li>\n        <li><span class=\"kw-clinique\">1ère crise de vertige chez l'enfant</span></li>\n        <li><span class=\"kw-clinique\">Grand vertige inaugural prolongé isolé</span> (recherche <span class=\"kw-clinique\">infarctus</span> cérébelleux)</li>\n      </ul>\n\n      <h4>2 · <span class=\"kw-imagerie\">IRM</span> centrée sur <span class=\"kw-clinique\">les</span> CAI et l'angle ponto-cérébelleux</h4>\n      <ul>\n        <li><strong>Déficit vestibulaire unilatéral persistant</strong> (sans <span class=\"kw-alerte\">urgence</span>) : recherche une <span class=\"kw-clinique\">lésion rétrocochléaire</span> (schwannome ++)</li>\n        <li><strong>Maladie de Ménière</strong> : selon master prépa, <span class=\"kw-imagerie\">IRM</span> des angles ponto-cérébelleux toujours réalisée pour éliminer un schwannome / autres processus expansifs</li>\n        <li><strong>Surdité de perception unilatérale</strong> (cf item 89)</li>\n      </ul>\n\n      <h4>3 · <span class=\"kw-imagerie\">TDM</span> des rochers</h4>\n      <p>Indiqué si <strong>signes otologiques associés</strong> au <span class=\"kw-clinique\">vertige</span> :</p>\n      <ul>\n        <li>Recherche signe de <span class=\"kw-clinique\">cholestéatome</span></li>\n        <li>Bilan des lésions osseuses (fracture du rocher, érosions, <span class=\"kw-clinique\">fistule</span>)</li>\n        <li>Mise en évidence d'une <span class=\"kw-clinique\">fistule</span> labyrinthique (opacité fenêtre cochléaire, pneumolabyrinthe, fracture/luxation platine)</li>\n      </ul>\n\n      <h4>4 · <span class=\"kw-imagerie\">IRM</span> avec séquences de <span class=\"kw-imagerie\">diffusion</span></h4>\n      <p>Possible pour <strong>discriminer un cholestéatome <span class=\"kw-bio\">vs</span> une otite chronique avec épanchement</strong> (le cholestéatome est en hypersignal sur la séquence de <span class=\"kw-imagerie\">diffusion</span>).</p>\n\n      <h4>5 · Synthèse des indications</h4>\n      <table >\n        <thead>\n          <tr><th>Tableau clinique</th><th>Imagerie</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Sd vestibulaire central / HINTS positif central / signes neuro</strong></td><td><span class=\"kw-imagerie\">IRM</span> cérébrale injectée + fosse postérieure + TSAO <span class=\"kw-alerte\">en urgence</span></td></tr>\n          <tr><td><strong>VPPB atypique / résistant aux manœuvres</strong></td><td><span class=\"kw-imagerie\">IRM</span> cérébrale</td></tr>\n          <tr><td><strong>1ère crise de <span class=\"kw-clinique\">vertige</span> chez l'enfant</strong></td><td><span class=\"kw-imagerie\">IRM</span> cérébrale</td></tr>\n          <tr><td><strong>Grand <span class=\"kw-clinique\">vertige</span> inaugural prolongé isolé</strong></td><td><span class=\"kw-imagerie\">IRM</span> cérébrale (recherche <span class=\"kw-clinique\">infarctus</span> cérébelleux)</td></tr>\n          <tr><td><strong>Déficit vestibulaire unilatéral persistant / suspicion schwannome</strong></td><td><span class=\"kw-imagerie\">IRM</span> CAI + APC avec gadolinium</td></tr>\n          <tr><td><strong>Maladie de Ménière confirmée</strong></td><td><span class=\"kw-imagerie\">IRM</span> APC pour éliminer un différentiel</td></tr>\n          <tr><td><strong>Signes otologiques (otorrhée, OMA, cholestéatome)</strong></td><td><span class=\"kw-imagerie\">TDM</span> des rochers ± <span class=\"kw-imagerie\">IRM</span> avec <span class=\"kw-imagerie\">diffusion</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>6 · Explorations vestibulaires et auditives (non-imagerie)</h4>\n      <table >\n        <thead>\n          <tr><th>Examen</th><th>Apport</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Vidéonystagmographie (VNG)</strong></td><td>Enregistre <span class=\"kw-clinique\">les</span> nystagmus spontanés ou induits (stimulations caloriques ou rotatoires)</td></tr>\n          <tr><td><strong>VHIT</strong> (Vidéo Head Impulse Test)</td><td>Version filmée du Halmagyi avec enregistrement</td></tr>\n          <tr><td><strong>Posturographie</strong></td><td>Exploration statique et dynamique de l'équilibre</td></tr>\n          <tr><td><strong>Verticale subjective</strong></td><td>Arguments pour pathologie des voies issues des macules otolithiques</td></tr>\n          <tr><td><strong>Audiométrie tonale</strong></td><td>Différencie ST <span class=\"kw-bio\">vs</span> SP</td></tr>\n          <tr><td><strong>Audiométrie vocale</strong></td><td>Détecte une SP rétrocochléaire (schwannome) — intelligibilité effondrée</td></tr>\n          <tr><td><strong>PEA</strong> (potentiels évoqués auditifs)</td><td>Exploration de toute la voie auditive · utiles pour éliminer une <span class=\"kw-clinique\">étiologie rétrocochléaire</span> (allongement des latences)</td></tr>\n          <tr><td><strong>Réflexes stapédiens</strong></td><td>Exploration de l'arc réflexe auditif</td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 340 — <span class=\"kw-def\">AVC</span> · 89 — Altération fonction auditive</em></p>","frequence":2},{"id":"103-13","rang":"B","rubrique":"Prise en charge","titre":"Connaître les principes du traitement symptomatique de la crise vertigineuse","contenu":"<p>Le traitement de la crise vertigineuse aiguë vise à <span class=\"kw-def\">réduire l'intensité des symptômes</span> (<span class=\"kw-clinique\">vertige</span> + signes végétatifs) pour permettre la <span class=\"kw-def\">reprise précoce de l'orthostatisme</span> et la <span class=\"kw-def\">compensation centrale</span>. Il combine traitements <span class=\"kw-etio\">médicamenteux</span> et mesures non médicamenteuses.</p>\n\n      <h4>1 · Traitement <span class=\"kw-etio\">médicamenteux</span> symptomatique</h4>\n      <table >\n        <thead>\n          <tr><th>Classe</th><th>Molécules</th><th>Particularités</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Antivertigineux majeurs</strong> (sédatifs, vestibuloplégiques)</td><td><span class=\"kw-ttt\">BZD</span> · <span class=\"kw-ttt\">Chlorhydrate de méclozine</span></td><td>Crise intense — sédatifs +++</td></tr>\n          <tr><td><strong>Antivertigineux mineurs</strong> (compensateurs et préventifs, peu sédatifs)</td><td><span class=\"kw-ttt\">Acétyl-leucine</span> (Tanganil) · <span class=\"kw-ttt\">Piracétam</span> · <span class=\"kw-ttt\">Bétahistidine</span></td><td>Favorisent la compensation</td></tr>\n          <tr><td><strong>Antiémétiques antagonistes 5-HT3</strong></td><td><span class=\"kw-ttt\">Ondansétron</span></td><td>Efficace sur <span class=\"kw-clinique\">nausées</span>/<span class=\"kw-clinique\">vomissements</span></td></tr>\n          <tr><td><strong>Antiémétiques neuroleptiques</strong></td><td><span class=\"kw-ttt\">Métoclopramide</span> · <span class=\"kw-ttt\">Métopimazine</span> · <span class=\"kw-ttt\">Dompéridone</span></td><td>Alternative aux 5-HT3</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · En cas d'échec du traitement ambulatoire</h4>\n      <ol>\n        <li><strong><span class=\"kw-alerte\">Hospitalisation</span></strong></li>\n        <li>Traitement IV : <span class=\"kw-ttt\">corticoïdes</span>, <span class=\"kw-ttt\">piracétam</span>, <span class=\"kw-ttt\">BZD</span>, <span class=\"kw-ttt\">mannitol</span></li>\n      </ol>\n\n      <h4>3 · Traitement <span class=\"kw-etio\">médicamenteux</span> de fond — selon l'étiologie</h4>\n      <table >\n        <thead>\n          <tr><th>Étiologie</th><th>Traitement de fond</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Maladie de Ménière</strong></td><td><span class=\"kw-ttt\">Bétahistidine</span> · <span class=\"kw-ttt\">diurétiques</span> (acétazolamide, <span class=\"kw-ttt\">furosémide</span>, <span class=\"kw-ttt\">spironolactone</span>) · <span class=\"kw-ttt\">corticoïdes</span> per os 8 j · agents osmotiques (glycérol)</td></tr>\n          <tr><td><strong><span class=\"kw-def\">Migraine</span> vestibulaire</strong></td><td>Anti-migraineux : <span class=\"kw-ttt\">flunarizine</span> · <span class=\"kw-ttt\">cinnarizine</span> (cf item 100)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Mesures non médicamenteuses</h4>\n      <table >\n        <thead>\n          <tr><th>Mesure</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Repos au lit</strong></td><td>Pendant la phase aiguë uniquement</td></tr>\n          <tr><td><strong>CI conduite automobile</strong></td><td>Jusqu'au diagnostic précis et la <span class=\"kw-ci\">normalisation fonctionnelle</span></td></tr>\n          <tr><td><strong>Lever précoce</strong></td><td>Dès <span class=\"kw-chiffre\">48 h</span> : arrêt des dépresseurs vestibulaires, encourager <span class=\"kw-clinique\">les</span> positions qui déclenchent le <span class=\"kw-clinique\">vertige</span></td></tr>\n          <tr><td><strong>Rééducation vestibulaire</strong></td><td>Prescrite d'emblée par <span class=\"kw-clinique\">kinésithérapeute spécialisé</span> · soumise à accord préalable CPAM · orientée par <span class=\"kw-clinique\">les</span> résultats de la vestibulométrie. Objectifs selon la cause :\n            <ul>\n              <li><strong><span class=\"kw-clinique\">Vertiges</span> récurrents :</strong> habituation aux symptômes (hors crises)</li>\n              <li><strong>VPPB :</strong> traitement étiologique par manœuvres thérapeutiques (1-2 séances)</li>\n              <li><strong>Déficit vestibulaire unilatéral aigu</strong> (névrite, fracture du rocher) : favoriser la compensation (10-12 séances,<span class=\"kw-chiffre\"> 1/jour</span> la 1ère semaine)</li>\n            </ul>\n          </td></tr>\n        </tbody>\n      </table>\n\n      <div class=\"callout callout-warn\">\n        <strong>⚠️ Limiter <span class=\"kw-clinique\">les</span> dépresseurs vestibulaires dans le temps.</strong> Arrêter les antivertigineux sédatifs à <span class=\"kw-clinique\">48 h</span> — ils <span class=\"kw-alerte\">freinent la compensation centrale</span>. Seule prescription pharmacologique possible au-delà : un antiémétique (<span class=\"kw-ttt\">dompéridone</span>) si <span class=\"kw-clinique\">nausées</span> persistantes.\n      </div>\n\n      <h4>5 · Particularité du sujet âgé</h4>\n      <p>Prise en charge <span class=\"kw-def\">multidisciplinaire</span> (podologue, kiné, ophtalmologue, gériatre) :</p>\n      <ul>\n        <li>Recherche et traitement de toute <strong>cause modifiable de chute</strong> (VPPB, interactions médicamenteuses, <span class=\"kw-clinique\">hypotension</span> orthostatique, pathologie ostéoarticulaire, chaussage inadapté, atteinte visuelle, atteinte auditive)</li>\n        <li>Réassurance, stimulation et entraînement physique</li>\n        <li>Recherche de <span class=\"kw-def\">dépression</span>, anxiété, troubles du sommeil</li>\n        <li>Rééducation kiné adaptée (proprioceptive + vestibulaire)</li>\n        <li>Correction de carences (protéique, vitaminique)</li>\n      </ul>","frequence":0},{"id":"103-14","rang":"B","rubrique":"Prise en charge","titre":"Connaître le principe des manœuvres diagnostique et thérapeutique d’un VPPB","contenu":"<p>Le VPPB se prend en charge entièrement <strong>sans médicament</strong> : <span class=\"kw-def\">manœuvre diagnostique</span> (Dix-Hallpike) puis <span class=\"kw-def\">manœuvre thérapeutique</span> (Epley ou Semont) — l'efficacité est immédiate et la guérison obtenue dans <span class=\"kw-chiffre\">80-90%</span> des cas.</p>\n\n      <h4>1 · Manœuvre diagnostique — Dix-Hallpike</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Objectif</strong></td><td>Rechercher un VPPB par atteinte des canaux semi-circulaires postérieurs droit ou gauche (forme la plus fréquente)</td></tr>\n          <tr><td><strong>Réalisation</strong></td><td>\n            <ol>\n              <li>Sujet <strong>assis</strong> sur la table d'examen</li>\n              <li>Tête tournée à <strong>45°</strong> vers le côté testé</li>\n              <li>Basculer rapidement en <strong>décubitus latéral</strong>, tête en extension (nez et regard au plafond)</li>\n              <li>Observer 30-60 s : nystagmus + <span class=\"kw-clinique\">vertige</span> reproduit ?</li>\n              <li>Remise en position assise (nystagmus s'inverse)</li>\n              <li>Refaire la manœuvre de l'autre côté</li>\n            </ol>\n          </td></tr>\n          <tr><td><strong>VPPB confirmé si</strong></td><td>Nystagmus avec : latence <span class=\"kw-bio\">5-15 s</span> · vertical supérieur + rotatoire <span class=\"kw-bio\">battant vers le sol</span> · crescendo-decrescendo · <span class=\"kw-bio\">durée ≤ 1 min</span> · accompagné d'un violent <span class=\"kw-clinique\">vertige</span> · <span class=\"kw-clinique\">s'inverse à la remise en position assise</span> · décubitus controlatéral négatif · fat<span class=\"kw-chiffre\">iga</span>ble</td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Manœuvres thérapeutiques — 2 types équivalents</h4>\n      <p>Objectif : <span class=\"kw-def\">libérer le canal semi-circulaire postérieur des débris d'otoconies</span> via une rotation de 180° dans le plan du canal vers l'avant.</p>\n\n      <table >\n        <thead>\n          <tr><th>Manœuvre</th><th>Type</th><th>Principe</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Manœuvre d'Epley</strong></td><td>Repositionnement des particules</td><td>Mobilisation progressive des otolithes par rotations successives de la tête à 90°, chaque position maintenue ~<span class=\"kw-chiffre\">1 min</span> 30, pour amener <span class=\"kw-clinique\">les</span> particules du canal postérieur vers le vestibule (où elles sont réabsorbées)</td></tr>\n          <tr><td><strong>Manœuvre de Semont</strong></td><td>Libératoire</td><td>Bascule rapide de 180° d'un côté à l'autre, sans changer la position de la tête, front contre le matelas — <span class=\"kw-def\">accélération brutale</span> pour décoincer <span class=\"kw-clinique\">les</span> otolithes par effet inertiel</td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Procédure Epley (canal postérieur droit)</h4>\n      <ol>\n        <li><strong>Phase 1 — Hallpike :</strong> patient assis, tête tournée à 45° à droite → bascule en décubitus latéral droit avec tête en hyperextension. Pause <strong><span class=\"kw-chiffre\">1 min</span> 30</strong>.</li>\n        <li><strong>Phase 2 :</strong> rotation de la tête à 90° vers la <strong>gauche</strong> (sans relever le corps). Pause <strong><span class=\"kw-chiffre\">1 min</span> 30</strong>.</li>\n        <li><strong>Phase 3 :</strong> patient tourné sur le côté gauche, tête inclinée à 90° vers le bas. Pause <strong><span class=\"kw-chiffre\">1 min</span> 30</strong>.</li>\n        <li>Redressement lent en position assise.</li>\n      </ol>\n\n      <figure class=\"obj-figure\">\n        <svg class=\"atlas-fig\" viewBox=\"0 0 560 244\" role=\"img\" aria-label=\"Frise des manœuvres positionnelles d'un VPPB du canal postérieur droit. Étape 1, manœuvre de Dix-Hallpike, à visée diagnostique : le patient assis a la tête tournée à 45 degrés vers la droite, puis on le bascule en décubitus tête en extension, ce qui reproduit le nystagmus et le vertige. Les étapes suivantes constituent la manœuvre thérapeutique d'Epley, chaque position étant maintenue environ une minute trente. Étape 2 : on tourne la tête de 90 degrés vers la gauche, le corps restant couché. Étape 3 : on tourne le patient sur le côté gauche, tête inclinée à 90 degrés vers le bas. Étape 4 : redressement lent en position assise, libérant le canal des otolithes.\" style=\"height:auto;display:block;border-radius:8px\">\n          <!-- Bandeau phases -->\n          <rect class=\"fb-grey\" x=\"14\" y=\"10\" width=\"128\" height=\"22\" rx=\"5\"/>\n          <text class=\"tx-grey\" x=\"78\" y=\"25\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">Diagnostic</text>\n          <rect class=\"fb-ok\" x=\"150\" y=\"10\" width=\"396\" height=\"22\" rx=\"5\"/>\n          <text class=\"tx-ok\" x=\"348\" y=\"25\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\">Thérapeutique — Epley (canal postérieur droit)</text>\n          <!-- Étape 1 — Dix-Hallpike -->\n          <rect class=\"fb-grey\" x=\"14\" y=\"42\" width=\"128\" height=\"148\" rx=\"6\"/>\n          <text class=\"tx-grey\" x=\"78\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">1 · Dix-Hallpike</text>\n          <line class=\"ln\" x1=\"34\" y1=\"118\" x2=\"122\" y2=\"118\" stroke-width=\"2\"/>\n          <ellipse class=\"fb-grey\" cx=\"56\" cy=\"104\" rx=\"13\" ry=\"13\"/>\n          <line class=\"ln\" x1=\"56\" y1=\"117\" x2=\"56\" y2=\"150\" stroke-width=\"3\"/>\n          <text class=\"tx-grey\" x=\"78\" y=\"161\" text-anchor=\"middle\" font-size=\"9\">assis, tête 45°</text>\n          <text class=\"tx-grey\" x=\"78\" y=\"172\" text-anchor=\"middle\" font-size=\"9\">à droite puis</text>\n          <text class=\"tx-grey\" x=\"78\" y=\"183\" text-anchor=\"middle\" font-size=\"9\">décubitus + extension</text>\n          <!-- Étape 2 — Epley P2 -->\n          <rect class=\"fb-amber\" x=\"150\" y=\"42\" width=\"128\" height=\"148\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"214\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">2 · tête 90° G</text>\n          <line class=\"ln\" x1=\"170\" y1=\"118\" x2=\"258\" y2=\"118\" stroke-width=\"2\"/>\n          <ellipse class=\"fb-amber\" cx=\"214\" cy=\"104\" rx=\"13\" ry=\"13\"/>\n          <line class=\"ln\" x1=\"170\" y1=\"150\" x2=\"258\" y2=\"150\" stroke-width=\"3\"/>\n          <text class=\"tx-amber\" x=\"214\" y=\"170\" text-anchor=\"middle\" font-size=\"9.5\">corps couché</text>\n          <text class=\"tx-amber\" x=\"214\" y=\"183\" text-anchor=\"middle\" font-size=\"9.5\">pause <span class=\"kw-chiffre\">1 min</span> 30</text>\n          <!-- Étape 3 — Epley P3 -->\n          <rect class=\"fb-amber\" x=\"286\" y=\"42\" width=\"128\" height=\"148\" rx=\"6\"/>\n          <text class=\"tx-amber\" x=\"350\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">3 · côté gauche</text>\n          <line class=\"ln\" x1=\"306\" y1=\"150\" x2=\"394\" y2=\"150\" stroke-width=\"3\"/>\n          <ellipse class=\"fb-amber\" cx=\"350\" cy=\"120\" rx=\"13\" ry=\"13\"/>\n          <line class=\"ln\" x1=\"350\" y1=\"133\" x2=\"372\" y2=\"148\" stroke-width=\"3\"/>\n          <text class=\"tx-amber\" x=\"350\" y=\"162\" text-anchor=\"middle\" font-size=\"9\">tête inclinée</text>\n          <text class=\"tx-amber\" x=\"350\" y=\"173\" text-anchor=\"middle\" font-size=\"9\">90° au sol</text>\n          <text class=\"tx-amber\" x=\"350\" y=\"184\" text-anchor=\"middle\" font-size=\"9.5\">pause <span class=\"kw-chiffre\">1 min</span> 30</text>\n          <!-- Étape 4 — retour assis -->\n          <rect class=\"fb-ok\" x=\"422\" y=\"42\" width=\"124\" height=\"148\" rx=\"6\"/>\n          <text class=\"tx-ok\" x=\"484\" y=\"62\" text-anchor=\"middle\" font-size=\"11.5\" font-weight=\"700\">4 · assis</text>\n          <ellipse class=\"fb-ok\" cx=\"484\" cy=\"92\" rx=\"13\" ry=\"13\"/>\n          <line class=\"ln\" x1=\"484\" y1=\"105\" x2=\"484\" y2=\"150\" stroke-width=\"3\"/>\n          <line class=\"ln\" x1=\"464\" y1=\"150\" x2=\"504\" y2=\"150\" stroke-width=\"2\"/>\n          <text class=\"tx-ok\" x=\"484\" y=\"170\" text-anchor=\"middle\" font-size=\"9.5\">redressement lent</text>\n          <text class=\"tx-ok\" x=\"484\" y=\"183\" text-anchor=\"middle\" font-size=\"9.5\">canal libéré</text>\n          <!-- Flèches de progression -->\n          <polygon class=\"ah\" points=\"148,116 138,111 138,121\"/>\n          <polygon class=\"ah\" points=\"284,116 274,111 274,121\"/>\n          <polygon class=\"ah\" points=\"420,116 410,111 410,121\"/>\n          <!-- Pied de frise -->\n          <text class=\"tx-muted\" x=\"280\" y=\"222\" text-anchor=\"middle\" font-size=\"10.5\">Sans médicament ·<span class=\"kw-chiffre\"> 80–90 %</span> de guérison · récidive ~<span class=\"kw-chiffre\">20 %</span> la 1ʳᵉ année</text>\n        </svg>\n        <figcaption>Séquence positionnelle pas-à-pas : Dix-Hallpike confirme le VPPB, puis Epley repositionne <span class=\"kw-clinique\">les</span> otolithes du canal postérieur vers le vestibule. Chaque position thérapeutique est maintenue ~<span class=\"kw-chiffre\">1 min</span> 30.</figcaption>\n      </figure>\n\n      <h4>4 · Procédure Semont (canal postérieur droit)</h4>\n      <ol>\n        <li>Patient assis, tête tournée à 45° vers la gauche (côté sain) → bascule rapide vers le côté droit (côté atteint), tête toujours tournée → attendre disparition du <span class=\"kw-clinique\">vertige</span> et nystagmus</li>\n        <li>Bascule rapide vers le côté gauche, <span class=\"kw-clinique\">sans changer la position de la tête</span> → front sur le matelas → attendre disparition d'un nouveau <span class=\"kw-clinique\">vertige</span> transitoire</li>\n        <li>Retour lent en position assise, sans incliner la tête</li>\n      </ol>\n\n      <h4>5 · Efficacité et résultats</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Efficacité</strong></td><td><span class=\"kw-bio\">80-90 % de guérison</span> très rapide après une seule manœuvre (équivalente pour Epley et Semont)</td></tr>\n          <tr><td><strong>Récidive</strong></td><td><span class=\"kw-clinique\">20% la 1ère année</span> · traitée par <span class=\"kw-clinique\">les</span> mêmes manœuvres</td></tr>\n          <tr><td><strong>Traitement <span class=\"kw-etio\">médicamenteux</span></strong> ❌</td><td><span class=\"kw-clinique\">Sans intérêt</span> dans le VPPB (symptômes paroxystiques)</td></tr>\n        </tbody>\n      </table>\n\n      <h4>6 · Précautions et limites</h4>\n      <ul>\n        <li>Après la manœuvre, <strong>éviter de s'allonger immédiatement</strong> ou de faire des mouvements brusques pour ne pas déplacer à nouveau <span class=\"kw-clinique\">les</span> otolithes</li>\n        <li>La manœuvre peut provoquer une <span class=\"kw-clinique\">sensation de vertige transitoire</span> qui disparaît en quelques minutes — prévenir le patient</li>\n        <li>Si <span class=\"kw-clinique\">vertiges</span> persistants après plusieurs manœuvres : <span class=\"kw-clinique\">réévaluation et IRM cérébrale</span> pour éliminer une cause centrale (tumeur fosse postérieure, SEP, malformation d'Arnold-Chiari)</li>\n      </ul>\n\n      <h4>7 · Comparaison des manœuvres</h4>\n      <table >\n        <thead>\n          <tr><th>Manœuvre</th><th>Objectif</th><th>Canal traité</th><th>Mécanisme</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Dix-Hallpike</strong></td><td>Diagnostic</td><td>Postérieur</td><td>Déclenche le nystagmus</td></tr>\n          <tr><td><strong>Epley</strong></td><td>Thérapeutique</td><td>Postérieur</td><td>Repositionnement progressif des otolithes</td></tr>\n          <tr><td><strong>Semont</strong></td><td>Thérapeutique</td><td>Postérieur</td><td>Libération rapide par accélération</td></tr>\n          <tr><td><strong>Barbecue (Lempert)</strong></td><td>Thérapeutique</td><td>Latéral (horizontal)</td><td>Rotation complète du patient pour repositionner <span class=\"kw-clinique\">les</span> otolithes</td></tr>\n        </tbody>\n      </table>","frequence":2},{"id":"103-15","rang":"B","rubrique":"Contenu multimédia","titre":"Reconnaître un nystagmus vestibulaire horizonto-rotatoire","contenu":"<p>Le <strong>nystagmus vestibulaire horizonto-rotatoire</strong> est le signe oculomoteur caractéristique d'un syndrome vestibulaire <span class=\"kw-def\">périphérique</span>. Sa reconnaissance clinique permet d'orienter immédiatement le diagnostic topographique (périph <span class=\"kw-bio\">vs</span> central) au lit du patient.</p>\n\n      <h4>1 · Définition du nystagmus</h4>\n      <table >\n        <thead>\n          <tr><th>Item</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Définition</strong></td><td>Mouvement involontaire <span class=\"kw-def\">conjugué</span> des globes oculaires, caractérisé par une succession rythmée, ± régulière, de mouvements changeant alternativement de sens</td></tr>\n          <tr><td><strong>Physiologique</strong></td><td>Nystagmus induit par la rotation de la tête (stabilisation oculaire par le réflexe vestibulo-cochléaire)</td></tr>\n          <tr><td><strong>Pathologique</strong></td><td>Survient <strong>sans mouvement de la tête</strong></td></tr>\n        </tbody>\n      </table>\n\n      <h4>2 · Types de nystagmus</h4>\n      <table >\n        <thead>\n          <tr><th>Type</th><th>Caractéristique</th><th>Origine</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Nystagmus pendulaire</strong></td><td>Secousses ayant la <span class=\"kw-bio\">même vitesse</span> dans <span class=\"kw-clinique\">les</span> 2 sens</td><td><span class=\"kw-alerte\">❌ N'est PAS d'origine vestibulaire</span> (nystagmus <span class=\"kw-etio\">congénital</span>, infantile, dans le cadre d'une basse vision)</td></tr>\n          <tr><td><strong>Nystagmus à ressort</strong></td><td><span class=\"kw-bio\">2 secousses aller-retour de vitesses différentes</span> : phase lente + phase de retour rapide</td><td><span class=\"kw-bio\">✅ Origine vestibulaire</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>3 · Caractéristiques du nystagmus vestibulaire à préciser à l'examen</h4>\n      <table >\n        <thead>\n          <tr><th>Caractéristique</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Direction</strong></td><td>Horizontal, vertical, rotatoire, mixte (horizonto-rotatoire dans la névrite typique)</td></tr>\n          <tr><td><strong>Sens de battement</strong></td><td>Donné par le <span class=\"kw-def\">sens de la phase rapide</span> (secousse de rappel)</td></tr>\n          <tr><td><strong>Intensité</strong></td><td>Appréciée par le <span class=\"kw-bio\">nombre de secousses en 30 secondes</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>4 · Nystagmus périphérique typique (névrite vestibulaire)</h4>\n      <table >\n        <thead>\n          <tr><th>Caractéristique</th><th>Périphérique typique</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Spontané / provoqué ?</strong></td><td><span class=\"kw-bio\">Spontané</span></td></tr>\n          <tr><td><strong>Intermittent / permanent ?</strong></td><td><span class=\"kw-bio\">Permanent</span></td></tr>\n          <tr><td><strong>Direction</strong></td><td><span class=\"kw-bio\">Horizonto-rotatoire</span> — toujours dans la même direction et le même sens</td></tr>\n          <tr><td><strong>Sens du battement</strong></td><td><span class=\"kw-bio\">Bat du côté sain</span> (secousses rapides) — phase lente vers la <span class=\"kw-clinique\">lésion</span></td></tr>\n          <tr><td><strong>Variation avec le regard</strong></td><td><span class=\"kw-bio\">Ne change pas de direction</span> quelle que soit la position du regard (loi d'Alexandre : majoré dans le regard du côté de la phase rapide)</td></tr>\n          <tr><td><strong>Intensité</strong></td><td><span class=\"kw-bio\">Proportionnelle à l'intensité des symptômes vertigineux</span></td></tr>\n          <tr><td><strong>Fixation oculaire</strong></td><td><span class=\"kw-bio\">Inhibé / diminué par la fixation</span> ++ (lever l'inhibition par <span class=\"kw-clinique\">les</span> <span class=\"kw-def\">lunettes grossissantes de Frenzel</span> 20 dioptries ou la vidéonystagmoscopie par caméra occlusive)</td></tr>\n          <tr><td><strong><span class=\"kw-clinique\">Évolution</span></strong></td><td>Compensant rapidement</td></tr>\n        </tbody>\n      </table>\n\n      <h4>5 · <span class=\"kw-alerte\">Drapeaux rouges</span> → atteinte centrale</h4>\n      <table >\n        <thead>\n          <tr><th>Atypie</th><th>Origine évoquée</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Apparition / aggravation à la fixation</strong></td><td><span class=\"kw-alerte\">Central</span></td></tr>\n          <tr><td><strong>Vertical pur</strong></td><td><span class=\"kw-alerte\">Lésion mésencéphalique</span></td></tr>\n          <tr><td><strong>Rotatoire pur</strong></td><td><span class=\"kw-alerte\">Lésion bulbaire</span></td></tr>\n          <tr><td><strong>Multidirectionnel</strong> (change de sens / direction selon le regard)</td><td><span class=\"kw-alerte\">Central</span></td></tr>\n          <tr><td><strong>Gaze nystagmus</strong> (à droite dans le regard à droite, à gauche dans le regard à gauche)</td><td><span class=\"kw-alerte\">Central</span></td></tr>\n          <tr><td><strong>Intensité non proportionnelle aux symptômes</strong></td><td><span class=\"kw-alerte\">Central</span></td></tr>\n        </tbody>\n      </table>\n\n      <h4>6 · Conditions de recherche du nystagmus</h4>\n      <table >\n        <thead>\n          <tr><th>Condition</th><th>Détail</th></tr>\n        </thead>\n        <tbody>\n          <tr><td><strong>Spontané</strong></td><td>Regard vers l'avant, sous lunettes de Frenzel (lève la fixation)</td></tr>\n          <tr><td><strong>Excentration du regard</strong></td><td>Le nystagmus périphérique est <strong>souvent retrouvé dans la direction de la phase rapide</strong> (ex. phase rapide à gauche → nystagmus retrouvé dans le regard à gauche)</td></tr>\n          <tr><td><strong>Manœuvre de Dix-Hallpike</strong></td><td>Pour le VPPB</td></tr>\n          <tr><td><strong>Vidéonystagmographie (VNG)</strong></td><td>Quantification objective des nystagmus spontanés ou induits (épreuves caloriques, rotatoires)</td></tr>\n          <tr><td><strong>Suppression de la fixation</strong></td><td>Lunettes de Frenzel 20 dioptries OU vidéonystagmoscopie par caméra occlusive</td></tr>\n        </tbody>\n      </table>\n\n      <h4>7 · Caractère constant ?</h4>\n      <ul>\n        <li>Le nystagmus peut <strong>manquer</strong> au syndrome vestibulaire (notamment dans <span class=\"kw-clinique\">les</span> syndromes vestibulaires <span class=\"kw-clinique\">incomplets</span>)</li>\n        <li>Tout <strong>nystagmus <span class=\"kw-etio\">acquis</span> signe l'existence d'un syndrome vestibulaire</strong></li>\n        <li>Nystagmus non vestibulaires possibles : nystagmus infantile, nystagmus pendulaire, nystagmus du regard excentré (regard extrême, fatigué)</li>\n      </ul>\n\n      <div class=\"callout callout-warn\">\n        <strong>À compléter.</strong> Une vidéo ou un schéma annoté de nystagmus vestibulaire horizonto-rotatoire (sous lunettes de Frenzel) sera ajouté ultérieurement dans <code>assets/images/103/</code> — la fiche source ne contient pas de capture directe et Kevin enrichira cet objectif avec une vidéo Pilly/Collège pertinente lors d'un B-FIX (ou via lien embed YouTube si autorisé).\n      </div>\n      <!-- TODO Kevin : ajouter vidéo ou schéma nystagmus horizonto-rotatoire dans assets/images/103/ -->","frequence":0,"liens":[{"href":"https://radiopaedia.org/articles/inner-ear","label":"Radiopaedia : Inner ear (anatomie)"},{"href":"https://radiopaedia.org/cases/inner-ear-anatomy-annotated-ct-3","label":"Radiopaedia : Inner ear anatomy (CT)"},{"href":"https://radiopaedia.org/articles/cerebellar-infarction","label":"Radiopaedia : Cerebellar infarction"},{"href":"https://radiopaedia.org/articles/benign-paroxysmal-positional-vertigo","label":"Radiopaedia : VPPB"},{"href":"https://radiopaedia.org/articles/meniere-disease","label":"Radiopaedia : Maladie de Ménière"},{"href":"https://radiopaedia.org/articles/vestibular-schwannoma","label":"Radiopaedia : Vestibular schwannoma (neurinome)"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Enjeu :</strong> ne pas confondre un <span class=\"kw-etio\">vertige périphérique bénin</span> avec un <span class=\"kw-alerte\">AVC vertébro-basilaire</span> / <span class=\"kw-alerte\">infarctus cérébelleux</span> (atteinte du <span class=\"kw-etio\">lobe floculo-nodulaire</span>).<br><strong>1er geste :</strong> réaliser le <span class=\"kw-clinique\">test HINTS</span> au lit du patient, <span class=\"kw-chiffre\">plus sensible que l'IRM dans les premières heures</span> d'un grand <span class=\"kw-clinique\">vertige</span> aigu.<br><strong>Fenêtre :</strong> si origine centrale, respecter <span class=\"kw-clinique\">les</span> <span class=\"kw-chiffre\">délais de thrombolyse / thrombectomie</span> par mutation en <span class=\"kw-ttt\">unité neurovasculaire</span>.<br><strong>À éliminer aussi :</strong> <span class=\"kw-etio\">cholestéatome</span> compliqué (<span class=\"kw-ttt\">chirurgie</span> en <span class=\"kw-alerte\">urgence</span>) et <span class=\"kw-etio\">dissection de l'artère vertébrale</span>.</p>","hospit":"<p><strong>Ambulatoire :</strong> <span class=\"kw-etio\">VPPB</span> et la plupart des <span class=\"kw-etio\">vertiges périphériques isolés</span> sans <span class=\"kw-alerte\">red flag</span>.<br><strong><span class=\"kw-alerte\">Hospitalisation</span> :</strong> <span class=\"kw-clinique\">échec du traitement symptomatique ambulatoire</span> (relais IV) ou <span class=\"kw-clinique\">vertige intense clouant au lit</span>.<br><strong><span class=\"kw-alerte\">Urgence</span> neurovasculaire :</strong> suspicion d'<span class=\"kw-alerte\">AVC vertébro-basilaire</span> → <span class=\"kw-ttt\">UNV</span> + <span class=\"kw-imagerie\">IRM cérébrale</span>.<br><strong>Avis ORL urgent :</strong> <span class=\"kw-etio\">labyrinthite otogène</span> / <span class=\"kw-etio\">cholestéatome</span> (<span class=\"kw-ttt\">chirurgie</span>) et <span class=\"kw-etio\">fistule labyrinthique</span> (exploration chirurgicale).</p>","redflags":"<ul><li><span class=\"kw-alerte\">Nystagmus vertical pur</span> ou <span class=\"kw-alerte\">multidirectionnel</span> changeant de sens selon la position du regard</li><li>Nystagmus <span class=\"kw-alerte\">non inhibé (voire aggravé) par la fixation oculaire</span></li><li><span class=\"kw-alerte\">Head Impulse Test normal</span> paradoxalement (absence de saccade de refixation)</li><li><span class=\"kw-alerte\">Skew deviation</span> (désalignement vertical des yeux) ou diplopie verticale</li><li><span class=\"kw-clinique\">Signes neurologiques associés</span> : <span class=\"kw-etio\">dysarthrie</span>, <span class=\"kw-etio\">diplopie</span>, <span class=\"kw-etio\">déficit moteur</span>, <span class=\"kw-etio\">syndrome cérébelleux</span></li><li><span class=\"kw-clinique\">Céphalées</span> ou <span class=\"kw-clinique\">cervicalgies</span> (évoquer une <span class=\"kw-etio\">dissection vertébrale</span>)</li><li>Présence de <span class=\"kw-clinique\">facteurs de risque cardio-vasculaire</span></li><li>Syndrome vestibulaire <span class=\"kw-alerte\">dysharmonieux</span> ou <span class=\"kw-alerte\">incomplet</span></li><li><span class=\"kw-alerte\">Grand vertige aigu isolé prolongé</span> (> <span class=\"kw-chiffre\">12 h</span>) : impose une <span class=\"kw-imagerie\">IRM</span> pour éliminer un <span class=\"kw-etio\">infarctus cérébelleux</span></li></ul>","principes":"<p><span class=\"kw-ttt\">Traitement symptomatique</span> de la crise commun à toutes <span class=\"kw-clinique\">les</span> causes, puis <span class=\"kw-ttt\">traitement étiologique</span> conditionnel selon le diagnostic.</p><p><strong>Traitement symptomatique de la crise</strong></p><p>Arrêt précoce des dépresseurs vestibulaires (à<span class=\"kw-chiffre\"> 48 h</span>) pour ne pas freiner la compensation centrale.</p><ul><li><span class=\"kw-ttt\">Antivertigineux majeurs</span> sédatifs : <span class=\"kw-ttt\">benzodiazépines</span>, <span class=\"kw-ttt\">chlorhydrate de méclozine</span></li><li><span class=\"kw-ttt\">Antiémétiques</span> : <span class=\"kw-ttt\">métoclopramide</span>, <span class=\"kw-ttt\">métopimazine</span>, <span class=\"kw-ttt\">dompéridone</span>, <span class=\"kw-ttt\">ondansétron</span></li><li><span class=\"kw-ttt\">Repos au lit</span> à la phase aiguë ; <span class=\"kw-ci\">conduite automobile contre-indiquée</span> jusqu'à normalisation</li><li>Si échec ambulatoire : <span class=\"kw-clinique\">hospitalisation</span> + <span class=\"kw-ttt\">corticoïdes</span> / <span class=\"kw-ttt\">piracétam</span> / <span class=\"kw-ttt\">benzodiazépines</span> / <span class=\"kw-ttt\">mannitol</span> en IV</li></ul><p><strong>VPPB</strong></p><p>Récidive ~<span class=\"kw-chiffre\">20 %</span> la 1re année, retraitée à l'identique.</p><ul><li><span class=\"kw-ttt\">Manœuvres libératoires</span> adaptées au canal atteint : <span class=\"kw-ttt\">Epley</span> (repositionnement) ou <span class=\"kw-ttt\">Semont</span> (libératoire)</li><li><span class=\"kw-chiffre\">80-90 %</span> de guérison, souvent en <span class=\"kw-chiffre\">1 à 2 séances</span></li><li><span class=\"kw-ci\">Traitement médicamenteux sans intérêt</span> (symptômes paroxystiques)</li></ul><p><strong>Névrite vestibulaire</strong></p><p>Il ne s'agit pas d'une rééducation de la marche.</p><ul><li>Symptomatique pendant <span class=\"kw-chiffre\">48 h</span> (<span class=\"kw-ttt\">dépresseurs vestibulaires</span> + <span class=\"kw-ttt\">antiémétiques</span>)</li><li>Puis <span class=\"kw-ttt\">arrêt des dépresseurs</span> et lever précoce du patient</li><li><span class=\"kw-ttt\">Rééducation vestibulaire</span> précoce pour <span class=\"kw-clinique\">favoriser la compensation centrale</span> (<span class=\"kw-chiffre\">10-12 séances</span>)</li></ul><p><strong>Maladie de Ménière</strong></p><p>Contrôle des <span class=\"kw-clinique\">vertiges</span> dans ~<span class=\"kw-chiffre\">70 %</span> des cas par le traitement médical.</p><ul><li><span class=\"kw-ttt\">Bétahistine</span> (antivertigineux de fond) et <span class=\"kw-ttt\">régime peu salé</span></li><li><span class=\"kw-ttt\">Diurétiques</span> (acétazolamide, <span class=\"kw-ttt\">furosémide</span>) ; <span class=\"kw-ttt\">corticoïdes</span> courts si <span class=\"kw-clinique\">poussée</span></li><li>En cas d'échec : <span class=\"kw-ttt\">gentamicine transtympanique</span> (labyrinthectomie chimique) ou <span class=\"kw-ttt\">chirurgie</span></li></ul><p><strong><span class=\"kw-alerte\">AVC</span> vertébro-basilaire</strong></p><p><span class=\"kw-imagerie\">IRM cérébrale</span> avec étude de la fosse postérieure et des TSAO.</p><ul><li><span class=\"kw-alerte\">Urgence neurologique</span> : <span class=\"kw-ttt\">mutation en unité neurovasculaire</span></li><li><span class=\"kw-ttt\">Thrombolyse / thrombectomie</span> si <span class=\"kw-clinique\">les</span> délais sont respectés</li></ul>","suivi":"<p><strong>Rééducation :</strong> <span class=\"kw-ttt\">rééducation vestibulaire</span> par kinésithérapeute (habituation pour <span class=\"kw-clinique\">vertiges</span> récurrents, compensation pour déficit unilatéral).<br><strong>Conduite :</strong> <span class=\"kw-ci\">conduite automobile contre-indiquée</span> jusqu'au diagnostic précis et à la normalisation fonctionnelle.<br><strong>Schwannome vestibulaire :</strong> <span class=\"kw-def\">surveillance</span> <span class=\"kw-imagerie\">IRM</span> + <span class=\"kw-bio\">audiométrie</span> (surveillance, <span class=\"kw-ttt\">radiothérapie</span> ou <span class=\"kw-ttt\">chirurgie</span> selon taille/évolutivité).<br><strong>Ménière :</strong> surveiller l'<span class=\"kw-bio\">audiogramme</span> (risque de <span class=\"kw-alerte\">cophose</span> et de <span class=\"kw-alerte\">bilatéralisation</span> dans <span class=\"kw-chiffre\">10-15 %</span>).</p>"},"liensGlobaux":[{"href":"https://www.cen-neurologie.fr/second-cycle/vertige","label":"Collège CEN — Vertige"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Syndrome vestibulaire aigu — <span class=\"kw-clinique\">Vertige rotatoire</span> + <span class=\"kw-clinique\">nystagmus</span> + <span class=\"kw-clinique\">ataxie vestibulaire</span> + <span class=\"kw-clinique\">signes neurovégétatifs</span>","detail":"<h4>CAT — <span class=\"kw-clinique\">Vertige</span> aigu / syndrome vestibulaire — Orientation périphérique <span class=\"kw-bio\">vs</span> centrale puis étiologique</h4>","branches":[{"to":"q-redflag","label":"Reconnaître le syndrome puis topographier","color":"blue"}]},{"id":"q-redflag","kind":"decision","label":"<span class=\"kw-alerte\">Red flags</span> d'atteinte centrale ou vasculaire ? — <span class=\"kw-alerte\">HINTS central</span>, <span class=\"kw-alerte\">nystagmus vertical/multidirectionnel non inhibé par la fixation</span>, <span class=\"kw-alerte\">HIT normal</span>, <span class=\"kw-alerte\">skew deviation</span>, <span class=\"kw-clinique\">signes neurologiques</span>, <span class=\"kw-clinique\">céphalée/cervicalgie</span>, <span class=\"kw-clinique\">FRCV</span>","branches":[{"to":"t-avc","label":"Oui — ≥ 1 critère central/vasculaire","color":"red"},{"to":"q-cochlee","label":"Non — syndrome harmonieux périphérique","color":"green"}]},{"id":"t-avc","kind":"terminal","label":"AVC vertébro-basilaire / infarctus cérébelleux — urgence","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Grand vertige</span> de plusieurs heures, <span class=\"kw-clinique\">syndrome vestibulaire central</span> ± <span class=\"kw-clinique\">syndrome cérébelleux</span> / <span class=\"kw-clinique\">dysarthrie</span></li><li><span class=\"kw-alerte\">HINTS central</span> : <span class=\"kw-alerte\">nystagmus multidirectionnel non inhibé</span> + <span class=\"kw-alerte\">skew deviation</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM cérébrale injectée</span> avec étude de la <span class=\"kw-imagerie\">fosse postérieure</span> et des <span class=\"kw-imagerie\">TSAO</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Mutation en unité neurovasculaire</span> en <span class=\"kw-alerte\">urgence</span></li><li><span class=\"kw-ttt\">Thrombolyse / thrombectomie</span> si délais respectés</li><li>Évoquer une <span class=\"kw-etio\">dissection vertébrale</span> si cervicalgie / traumatisme cervical</li></ul>"},{"id":"q-cochlee","kind":"decision","label":"Signes cochléaires ou otologiques associés ? — <span class=\"kw-clinique\">Surdité de perception</span>, <span class=\"kw-clinique\">acouphènes</span>, <span class=\"kw-clinique\">otorrhée</span> ou <span class=\"kw-clinique\">otoscopie anormale</span>","branches":[{"to":"q-otoscopie","label":"Oui — signes cochléaires/otologiques","color":"amber"},{"to":"q-duree","label":"Non — vertige isolé","color":"green"}]},{"id":"q-otoscopie","kind":"decision","label":"Otoscopie anormale ? — <span class=\"kw-clinique\">Otorrhée</span>, <span class=\"kw-etio\">cholestéatome</span>, <span class=\"kw-clinique\">hémotympan</span> à l'examen","branches":[{"to":"t-otogene","label":"Oui","color":"red"},{"to":"t-oreille-interne","label":"Non","color":"amber"}]},{"id":"t-otogene","kind":"terminal","label":"Cause otogène — TDM des rochers + avis ORL urgent","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Otoscopie anormale</span> : <span class=\"kw-clinique\">otorrhée</span>, <span class=\"kw-etio\">cholestéatome</span>, <span class=\"kw-clinique\">hémotympan</span> (fracture du rocher)</li><li><span class=\"kw-clinique\">Signe de la fistule</span> : <span class=\"kw-clinique\">vertige</span> + nystagmus à la pression du conduit</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">TDM des rochers</span> (recherche de cholestéatome / <span class=\"kw-clinique\">fistule</span>)</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-ttt\">Avis ORL urgent</span></li><li><span class=\"kw-ttt\">Antibiothérapie</span> + <span class=\"kw-ttt\">corticothérapie</span> ; <span class=\"kw-ttt\">chirurgie en urgence si cholestéatome</span></li></ul>"},{"id":"t-oreille-interne","kind":"terminal","label":"Atteinte de l'oreille interne — Ménière / schwannome / fistule","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-etio\">Maladie de Ménière</span> : crises (<span class=\"kw-chiffre\">15 min à quelques heures</span>) + <span class=\"kw-clinique\">acouphènes graves</span> + <span class=\"kw-clinique\">hypoacousie fluctuante</span> + plénitude</li><li><span class=\"kw-etio\">Schwannome vestibulaire</span> : <span class=\"kw-clinique\">surdité unilatérale progressive</span> + <span class=\"kw-clinique\">acouphènes aigus</span></li><li><span class=\"kw-etio\">Fistule périlymphatique</span> : <span class=\"kw-clinique\">surdité fluctuante</span> après barotraumatisme</li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-bio\">Audiométrie tonale et vocale</span>, <span class=\"kw-bio\">PEA</span></li><li><span class=\"kw-imagerie\">IRM des conduits auditifs internes</span> injectée (éliminer un schwannome)</li></ul><h4>Traitement</h4><ul><li>Ménière : <span class=\"kw-ttt\">bétahistine</span> + <span class=\"kw-ttt\">régime peu salé</span></li><li>Schwannome : <span class=\"kw-ttt\">surveillance / radiothérapie / chirurgie</span> selon taille</li></ul>"},{"id":"q-duree","kind":"decision","label":"Caractéristiques du <span class=\"kw-clinique\">vertige</span> isolé ? — Durée et caractère : <span class=\"kw-chiffre\">bref positionnel</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-chiffre\">prolongé unique</span> <span class=\"kw-bio\">vs</span> <span class=\"kw-chiffre\">transitoire inaugural</span>","branches":[{"to":"t-vppb","label":"Bref < 1 min, positionnel, répété","color":"green"},{"to":"t-nevrite","label":"Unique prolongé > 24 h","color":"amber"},{"to":"t-ait","label":"Transitoire < 1 h, inaugural","color":"red"}]},{"id":"t-vppb","kind":"terminal","label":"VPPB — manœuvre diagnostique puis libératoire","color":"green","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Vertiges</span> <span class=\"kw-clinique\">brefs (< 30 s)</span>, <span class=\"kw-clinique\">positionnels</span>, répétés et reproductibles</li><li>Asymptomatique entre les crises, <span class=\"kw-clinique\">pas de signe cochléaire ni neurologique</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-clinique\">Manœuvre de Dix et Hallpike</span> : nystagmus après <span class=\"kw-chiffre\">latence 5-15 s</span>, paroxystique, <span class=\"kw-clinique\">fatigable</span></li><li>Aucun autre examen si tableau typique</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Manœuvre libératoire (Epley / Semont)</span> : <span class=\"kw-chiffre\">80-90 %</span> de guérison</li><li><span class=\"kw-ci\">Pas de traitement médicamenteux</span></li></ul>"},{"id":"t-nevrite","kind":"terminal","label":"Névrite vestibulaire — symptomatique + rééducation","color":"amber","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Grand vertige unique prolongé</span> (<span class=\"kw-chiffre\">24-48 h</span>), installation brutale, permanent</li><li><span class=\"kw-clinique\">Syndrome vestibulaire harmonieux</span>, <span class=\"kw-clinique\">HINTS périphérique</span> (saccade de refixation, nystagmus inhibé par la fixation)</li><li><span class=\"kw-clinique\">Pas de signe cochléaire ni neurologique</span></li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">Symptomatique 48 h</span> (dépresseurs vestibulaires + antiémétiques) puis arrêt</li><li><span class=\"kw-ttt\">Rééducation vestibulaire</span> précoce (compensation centrale)</li></ul><h4><span class=\"kw-def\">Surveillance</span></h4><ul><li><span class=\"kw-def\">Diagnostic différentiel</span> = <span class=\"kw-etio\">infarctus cérébelleux</span> : <span class=\"kw-imagerie\">IRM</span> au moindre doute ou atypie</li></ul>"},{"id":"t-ait","kind":"terminal","label":"AIT vertébro-basilaire — bilan vasculaire urgent","color":"red","detail":"<h4>Clinique</h4><ul><li><span class=\"kw-clinique\">Vertige</span> <span class=\"kw-clinique\">brutal</span>, <span class=\"kw-clinique\">transitoire (< 1 h)</span>, inaugural</li><li>Rechercher signes vertébro-basilaires : <span class=\"kw-etio\">hémianopsie</span>, <span class=\"kw-etio\">paresthésies</span>, <span class=\"kw-etio\">ataxie</span>, <span class=\"kw-etio\">dysarthrie</span>, <span class=\"kw-etio\">diplopie</span></li></ul><h4>Paraclinique</h4><ul><li><span class=\"kw-imagerie\">IRM encéphalique</span> + exploration des <span class=\"kw-imagerie\">TSAO</span> et du polygone de Willis + <span class=\"kw-clinique\">ECG</span></li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Prise en charge en urgence comme un AIT</span></li><li>Diagnostic différentiel : 1re crise de <span class=\"kw-etio\">migraine vestibulaire</span> ou de <span class=\"kw-etio\">maladie de Ménière</span></li></ul>"}]},"cards":[{"i":"1e45e490c4b3","n":103,"o":"103-2","u":"Définition","t":"Connaître la définition du vertige","q":"Selon l'EDN, quelle est la définition précise du vertige ?","a":"<p>Le vertige est une <strong>illusion de mouvement</strong>, soit du patient, soit de l'environnement.</p>"},{"i":"91f206af13bf","n":103,"o":"103-2","u":"Définition","t":"Connaître la définition du vertige","q":"Quels systèmes du corps sont généralement atteints pour causer un vertige ?","a":"<p>Le vertige est causé par une atteinte du <strong>système d'équilibre au sens large</strong>, incluant le vestibule, le nerf vestibulaire, les noyaux vestibulaires, le cervelet vestibulaire et les voies centrales.</p>"},{"i":"9801bc5972cb","n":103,"o":"103-2","u":"Définition","t":"Connaître la définition du vertige","q":"Quels sont les signes d'accompagnement classiques du vertige, en tant que maître symptôme du syndrome vestibulaire ?","a":"<p>Le vertige est accompagné de :<ul><li>Signes neurovégétatifs : <strong>nausées, vomissements, sueurs, pâleur</strong>.</li><li>Un <strong>nystagmus</strong>.</li><li>Des <strong>déviations posturales</strong>.</li></ul></p>"},{"i":"9d9b400be799","n":103,"o":"103-2","u":"Définition","t":"Connaître la définition du vertige","q":"Comment les patients décrivent-ils le plus souvent cette illusion de mouvement caractéristique du vertige ?","a":"<p>Elle se traduit le plus souvent par une impression de <strong>rotation</strong> ou parfois de <strong>déplacement linéaire</strong> (chute, bascule).</p>"}]};